-- Navaratri Pooja and Saraswati Pooja, from the book.
-- Generated by scripts/build-navaratri-saraswati.mjs; do not edit by hand.
--
-- Source: Sampradaya Vratha Pooja Vidhi (Giri), sections 10 and 11, pp.283-324, transcribed page by page.
-- Two rites, as the source has them. Every mantra is read from the page
-- transcripts by book page and block; see the script header for the three
-- print repairs and the one feature of the source deliberately kept.

begin;

-- --- deities --------------------------------------------------------------------
insert into public.deities (id, name_en, name_deva, name_ta, name_dative_deva, class, dhyana_sloka_deva, avahana_deva)
values
  ('navaratri_devi', 'Durga, Lakshmi and Saraswati', 'श्रीदुर्गा लक्ष्मी सरस्वती', 'ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ',
   'श्रीदुर्गा लक्ष्मी सरस्वती देव्यै', 'goddess', 'महिषघ्नीं महादेवीं कुमारीं सिंहवाहिनीम्।
दानवांस्तर्जयन्तीम् च सर्वकामदुघां शिवाम्॥
ध्यायामि मनसा दुर्गां नाभिमध्ये व्यवस्थिताम्।
आगच्छ वरदे देवि दैत्यदर्पनिपातिनि॥
पूजां गृहाण सुमुखि नमस्ते शङ्करप्रिये।
सर्वतीर्थमयं वारि सर्वदेव समन्वितम्॥
इमं घटं समागच्छ तिष्ठ देवगणैस्सह।
दुर्गे देवि समागच्छ सान्निध्यं इह कल्पय॥
अस्मिन् कलशे(बिम्बे)श्रीदुर्गा लक्ष्मी सरस्वतीं ध्यायामि', 'एहि दुर्गे महाभागे रक्षार्थं मम सर्वदा।
आवाहयाम्यहं देवि सर्वकामार्थ सिद्धये॥
श्रीदुर्गा लक्ष्मी सरस्वतीं आवाहयामि'),
  ('saraswati', 'Saraswati', 'सरस्वती', 'ஸரஸ்வதீ',
   'श्री सरस्वती देव्यै', 'goddess', 'सरस्वतीं सत्यवासां सुधांशुसमविग्रहाम् ।
स्फटिकाक्षस्रजं पद्मं पुस्तकं च शुकं करैः।।
चतुर्भि-र्दधतीं देवीं चन्द्रबिंब समाननाम् ।
वल्लभामखिलार्थानां वल्लकीवादनप्रियाम् ।।
अस्मिन् पुस्तक मण्डले/ चित्रपटे/ वाद्यमण्डले
श्रीदुर्गा लक्ष्मी सरस्वतीं ध्यायामि', 'भारतीं भावये देवीं भाषाणामधिदेवताम् ।
भावितां हृदये सद्भि-र्भामिनीं परमेष्ठिनः।।
चतुर्भुजां चन्द्रवर्णां चतुरानन-वल्लभाम् ।।
अवाहयामि वाणि त्वामाश्रितार्ति-विनाशिनीम् ।।
अस्मिन् पुस्तक मण्डले/ चित्रपटे/ वाद्यमण्डले
श्रीदुर्गा लक्ष्मी सरस्वतीं आवाहयामि।।')
on conflict (id) do update set
  name_en = excluded.name_en, name_deva = excluded.name_deva, name_ta = excluded.name_ta,
  name_dative_deva = excluded.name_dative_deva,
  dhyana_sloka_deva = excluded.dhyana_sloka_deva, avahana_deva = excluded.avahana_deva,
  updated_at = now();

-- --- Navaratri Pooja ------------------------------------------------------------
insert into public.poojas
  (id, title_en, title_ta, ritual_class, deity_id, description_en, description_ta,
   duration_mins, eligibility, rule_type, rule_month, rule_reckoning, rule_paksha,
   rule_tithi, rule_notes, source_ref, karta_recommended, status, why_en, why_ta)
values ('navaratri_pooja', 'Navaratri Pooja', 'நவராத்திரி பூஜை', 'deity_pooja', 'navaratri_devi',
        'The nine nights of the Goddess in Purattasi, from the new moon to Navami, worshipped as Durga, Lakshmi and Saraswati together. The kalasham is installed on the first day, worshipped each day with the hundred and eight names, the nine Durgas and a kanya pooja, and released on Vijayadashami.',
        'புரட்டாசி அமாவாசைக்குப் பின் பிரதமை முதல் நவமி வரை தேவியின் ஒன்பது இரவுகள் — துர்கா, லக்ஷ்மீ, ஸரஸ்வதீ மூவரையும் சேர்த்து வழிபடுவது. முதல் நாள் கலசம் ப்ரதிஷ்டை செய்யப்பட்டு, நாள்தோறும் அஷ்டோத்தரம், நவதுர்கா, கன்யா பூஜையுடன் வழிபட்டு, விஜயதசமியன்று யதாஸ்தானம் செய்யப்படுகிறது.',
        75, 'all', 'tithi_in_month', 'ashvina', 'chandra', 'shukla',
        'prathama', 'Begins on Ashvina shukla prathama, the day after the Mahalaya new moon, in Purattasi or Aippasi of the solar year, and runs nine nights to Navami. Vijayadashami, the tenth day, is the release. If all nine days are not possible, keep at least the last three: Saptami, Ashtami and Navami.', 'Sampradaya Vratha Pooja Vidhi (Giri), pp.283-304',
        null, 'published',
        'The Goddess is worshipped for nine nights because the story behind them takes nine nights: in the Devi Mahatmyam, the gods could not defeat Mahishasura, and the Goddess who arose from their combined power fought him until she won on the tenth day, Vijayadashami, the day of victory. The household keeps those nights by worshipping her as three: Durga, who protects; Lakshmi, who provides; and Saraswati, who gives understanding, often three nights each. It is a festival of welcome as much as of worship. A golu of dolls is set up, sumangalis and young girls are invited, fed and sent home with turmeric, kumkumam and a gift, because the Goddess is honoured in them too. On the tenth day she is asked to return next year, and new things are begun.',
        'தேவி ஒன்பது இரவுகள் வழிபடப்படுவதற்குக் காரணம், அதன் பின்னுள்ள கதை ஒன்பது இரவுகள் நீடிப்பதே: தேவீ மாஹாத்மியத்தில், தேவர்களால் வெல்ல முடியாத மஹிஷாஸுரனை, அவர்களின் சக்திகள் ஒன்றுசேர்ந்து தோன்றிய தேவி எதிர்த்துப் போரிட்டு, பத்தாம் நாளான விஜயதசமியன்று வென்றாள். வீட்டில் அந்த இரவுகளை தேவியை மூவராக வழிபட்டு அனுஷ்டிக்கிறோம் — காக்கும் துர்கை, அருளும் லக்ஷ்மி, அறிவு தரும் ஸரஸ்வதி — பெரும்பாலும் ஒவ்வொருவருக்கும் மூன்று இரவுகள். இது வழிபாட்டுத் திருவிழா மட்டுமல்ல, வரவேற்புத் திருவிழாவும் கூட. கொலு வைக்கப்படுகிறது; சுமங்கலிகளும் சிறுமிகளும் அழைக்கப்பட்டு, உணவளிக்கப்பட்டு, மஞ்சள், குங்குமம், பரிசுடன் அனுப்பப்படுகிறார்கள் — அவர்களிடமும் தேவி வழிபடப்படுகிறாள். பத்தாம் நாள் அடுத்த ஆண்டு மீண்டும் வரும்படி அவளை வேண்டி, புதிய காரியங்கள் தொடங்கப்படுகின்றன.')
on conflict (id) do update set
  title_en = excluded.title_en, title_ta = excluded.title_ta,
  ritual_class = excluded.ritual_class, deity_id = excluded.deity_id,
  description_en = excluded.description_en, description_ta = excluded.description_ta,
  duration_mins = excluded.duration_mins, eligibility = excluded.eligibility,
  rule_type = excluded.rule_type, rule_month = excluded.rule_month,
  rule_reckoning = excluded.rule_reckoning, rule_paksha = excluded.rule_paksha,
  rule_tithi = excluded.rule_tithi, rule_notes = excluded.rule_notes,
  source_ref = excluded.source_ref, karta_recommended = excluded.karta_recommended,
  status = excluded.status, why_en = excluded.why_en, why_ta = excluded.why_ta,
  updated_at = now();

insert into public.pooja_modes (pooja_id, mode, seq, label_en, label_ta, hint_en, hint_ta) values
  ('navaratri_pooja', 'main', 1, 'First Day', 'முதல் நாள்', 'Prathama. Full vidhi: the kalasham is invoked and installed.', 'பிரதமை. முழு விதி: கலசம் ஆவாஹனம் செய்து ப்ரதிஷ்டை செய்யப்படுகிறது.'),
  ('navaratri_pooja', 'punar', 2, 'Days 2 to 9', 'இரண்டு முதல் ஒன்பதாம் நாள் வரை', 'The daily pooja. The Goddess is already installed.', 'தினசரி பூஜை. தேவி ஏற்கனவே ப்ரதிஷ்டை செய்யப்பட்டுள்ளாள்.'),
  ('navaratri_pooja', 'udvasana', 3, 'Vijayadashami – Punah Pooja', 'விஜயதசமி – புனர் பூஜை', 'The tenth day. Names, offerings, camphor and the release.', 'பத்தாம் நாள். நாமாவளி, உபசாரம், கற்பூரம், யதாஸ்தானம்.')
on conflict (pooja_id, mode) do update set
  seq = excluded.seq, label_en = excluded.label_en, label_ta = excluded.label_ta,
  hint_en = excluded.hint_en, hint_ta = excluded.hint_ta, updated_at = now();
delete from public.pooja_modes where pooja_id = 'navaratri_pooja' and mode not in ('main', 'punar', 'udvasana');

-- --- Saraswati Pooja ------------------------------------------------------------
insert into public.poojas
  (id, title_en, title_ta, ritual_class, deity_id, description_en, description_ta,
   duration_mins, eligibility, rule_type, rule_month, rule_reckoning, rule_paksha,
   rule_tithi, rule_notes, source_ref, karta_recommended, status, why_en, why_ta)
values ('saraswati_pooja', 'Saraswati Pooja', 'ஸரஸ்வதீ பூஜை', 'deity_pooja', 'saraswati',
        'The worship of Saraswati on Mahanavami, the ninth day of Navaratri, performed over books, musical instruments and the tools of one''s work. They are left untouched for the day and taken up again on Vijayadashami, when new learning is begun.',
        'நவராத்திரியின் ஒன்பதாம் நாளான மஹாநவமியன்று புத்தகங்கள், இசைக் கருவிகள், தொழில் கருவிகள் இவற்றின் மேல் ஸரஸ்வதியை வழிபடுவது. அன்று அவை தொடப்படுவதில்லை; விஜயதசமியன்று மீண்டும் எடுக்கப்பட்டு புதிய கல்வி தொடங்கப்படுகிறது.',
        60, 'all', 'tithi_in_month', 'ashvina', 'chandra', 'shukla',
        'navami', 'Mahanavami, Ashvina shukla navami, the ninth day of Navaratri. The books are released and taken up on Vijayadashami, the next morning.', 'Sampradaya Vratha Pooja Vidhi (Giri), pp.305-324',
        null, 'published',
        'Knowledge is what makes a person more than their circumstances, and the tradition gives that knowledge a face: Saraswati, the goddess of speech, learning and the arts. The story told for this day is of King Suketu, driven from his kingdom, whose queen was told by the sage Angiras to worship Saraswati on Navami; their son Suryaprabha grew up mastering every art and won the kingdom back. So on the ninth day of Navaratri the books, instruments and tools of the house are laid down and worshipped as the Goddess, and for one day nobody studies or works with them. The next morning, Vijayadashami, they are taken up again, children write their first letters, and whatever is begun is begun with her blessing.',
        'ஒருவரை அவர் சூழ்நிலைக்கு மேல் உயர்த்துவது அறிவு; அந்த அறிவுக்கு மரபு ஒரு வடிவம் தருகிறது — வாக்கு, கல்வி, கலைகளின் தேவியான ஸரஸ்வதி. இந்நாளுக்குச் சொல்லப்படும் கதை, ராஜ்யத்தை இழந்த ஸுகேது மன்னனுடையது: அங்கிரஸ முனிவர் சொன்னபடி அவன் நவமியன்று ஸரஸ்வதியை வழிபட, அவர்களின் மகன் ஸூர்யப்ரபன் எல்லாக் கலைகளிலும் தேர்ந்து ராஜ்யத்தை மீட்டான். எனவே நவராத்திரியின் ஒன்பதாம் நாள் வீட்டின் புத்தகங்கள், கருவிகள், தொழில் சாதனங்கள் அனைத்தும் தேவியாக வைத்து வழிபடப்படுகின்றன; அன்று யாரும் அவற்றைக் கொண்டு படிப்பதோ வேலை செய்வதோ இல்லை. மறுநாள் விஜயதசமியன்று அவை மீண்டும் எடுக்கப்படுகின்றன, குழந்தைகள் முதல் எழுத்துகளை எழுதுகிறார்கள், தொடங்குவது எதுவும் அவள் ஆசியுடன் தொடங்குகிறது.')
on conflict (id) do update set
  title_en = excluded.title_en, title_ta = excluded.title_ta,
  ritual_class = excluded.ritual_class, deity_id = excluded.deity_id,
  description_en = excluded.description_en, description_ta = excluded.description_ta,
  duration_mins = excluded.duration_mins, eligibility = excluded.eligibility,
  rule_type = excluded.rule_type, rule_month = excluded.rule_month,
  rule_reckoning = excluded.rule_reckoning, rule_paksha = excluded.rule_paksha,
  rule_tithi = excluded.rule_tithi, rule_notes = excluded.rule_notes,
  source_ref = excluded.source_ref, karta_recommended = excluded.karta_recommended,
  status = excluded.status, why_en = excluded.why_en, why_ta = excluded.why_ta,
  updated_at = now();

insert into public.pooja_modes (pooja_id, mode, seq, label_en, label_ta, hint_en, hint_ta) values
  ('saraswati_pooja', 'main', 1, 'Navami Pooja', 'நவமி பூஜை', 'Mahanavami. Full vidhi over the books and instruments.', 'மஹாநவமி. புத்தகங்கள், கருவிகளின் மேல் முழு விதி.'),
  ('saraswati_pooja', 'udvasana', 2, 'Vijayadashami – Punah Pooja', 'விஜயதசமி – புனர் பூஜை', 'The next morning. Names, offerings, and the books taken up again.', 'மறுநாள் காலை. நாமாவளி, உபசாரம், புத்தகங்களை மீண்டும் எடுத்தல்.')
on conflict (pooja_id, mode) do update set
  seq = excluded.seq, label_en = excluded.label_en, label_ta = excluded.label_ta,
  hint_en = excluded.hint_en, hint_ta = excluded.hint_ta, updated_at = now();
delete from public.pooja_modes where pooja_id = 'saraswati_pooja' and mode not in ('main', 'udvasana');

insert into public.namavalis (id, deity_id, recension, name_count, source_ref)
values ('durga_ashtottara_108', 'navaratri_devi', 'Opens shriyai, umayai, bharatyai; closes durgaparameshvaryai.', 108, 'Sampradaya Vratha Pooja Vidhi (Giri), pp.293-296; count markers verified in both scripts; name 91 read from the roman, the Devanagari glyph being unprinted')
on conflict (id) do update set deity_id = excluded.deity_id, recension = excluded.recension, source_ref = excluded.source_ref;
insert into public.namavali_items (namavali_id, seq, name_deva, name_ta, name_translit) values
  ('durga_ashtottara_108', 1, 'ॐ श्रियै नमः', 'ஓம் ஶ்ரியை நம꞉', 'oṃ śriyai namaḥ'),
  ('durga_ashtottara_108', 2, 'ॐ उमायै नमः', 'ஓம் உமாயை நம꞉', 'oṃ umāyai namaḥ'),
  ('durga_ashtottara_108', 3, 'ॐ भारत्यै नमः', 'ஓம் பாரத்யை நம꞉', 'oṃ bhāratyai namaḥ'),
  ('durga_ashtottara_108', 4, 'ॐ भद्रायै नमः', 'ஓம் பத்ராயை நம꞉', 'oṃ bhadrāyai namaḥ'),
  ('durga_ashtottara_108', 5, 'ॐ शर्वाण्यै नमः', 'ஓம் ஶர்வாண்யை நம꞉', 'oṃ śarvāṇyai namaḥ'),
  ('durga_ashtottara_108', 6, 'ॐ विजयायै नमः', 'ஓம் விஜயாயை நம꞉', 'oṃ vijayāyai namaḥ'),
  ('durga_ashtottara_108', 7, 'ॐ जयायै नमः', 'ஓம் ஜயாயை நம꞉', 'oṃ jayāyai namaḥ'),
  ('durga_ashtottara_108', 8, 'ॐ वाण्यै नमः', 'ஓம் வாண்யை நம꞉', 'oṃ vāṇyai namaḥ'),
  ('durga_ashtottara_108', 9, 'ॐ सर्वगतायै नमः', 'ஓம் ஸர்வகதாயை நம꞉', 'oṃ sarvagatāyai namaḥ'),
  ('durga_ashtottara_108', 10, 'ॐ गौर्यै नमः', 'ஓம் கௌர்யை நம꞉', 'oṃ gauryai namaḥ'),
