insert into public.namavalis (id, deity_id, recension, name_count, source_ref)
values ('saraswati_ashtottara_108', 'saraswati', 'Opens sarasvatyai, mahabhadrayai, mahamayayai; closes brahmavishnushivatmikayai. Mahabhadra, Vaishnavi and Vagdevi each occur twice.', 108, 'Sampradaya Vratha Pooja Vidhi (Giri), pp.315-318; count markers verified in both scripts')
on conflict (id) do update set deity_id = excluded.deity_id, recension = excluded.recension, source_ref = excluded.source_ref;
