  ('saraswati_ashtottara_108', 88, 'ॐ रूपसौभाग्यदायिन्यै नमः', 'ஓம் ரூபஸௌபாக்யதாயிந்யை நம꞉', 'oṃ rūpasaubhāgyadāyinyai namaḥ'),
