insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 5, 'purvangam', '{main,punar}', 'Manjal Pillaiyar Pooja', 'மஞ்சள் பிள்ளையார் பூஜை',
        'Shape a small cone of turmeric paste on a betel leaf and set it before the kalasham. Invoke Pillaiyar in it, offer akshatai and a flower, and ask that the nine days go without obstacle. On each of the following days the same turmeric Pillaiyar is worshipped again before the pooja begins.',
        'மஞ்சள் மாவை வெற்றிலையின் மேல் சிறு கூம்பாகப் பிடித்து கலசத்தின் முன் வைக்கவும். அதில் பிள்ளையாரை ஆவாஹனம் செய்து, அக்ஷதையும் புஷ்பமும் சமர்ப்பித்து, ஒன்பது நாட்களும் விக்கினமின்றி நடக்கும்படி வேண்டவும். அடுத்த நாட்களிலும் பூஜை தொடங்கும் முன் இதே மஞ்சள் பிள்ளையாரைப் பூஜிக்கவும்.',
        'हरिद्राभं चतुर्बाहुं हरिद्रावदनं प्रभुम् ।
पाशांकुशधरं देवं मोदकं दंतमेव च ।
भक्ताऽभयप्रदातारं वंदे विघ्नविनाशनम् ।
ॐ हरिद्रा गणपतये नमः ।
अस्मिन् हरिद्राबिंबे श्रीमहागणपतिं आवाहयामि, स्थापयामि, पूजयामि ॥',
        'ஹரித்ராபம் சதுர்பாஹும் ஹரித்ராவதநம் ப்ரபும் ।
பாஶாம்குஶதரம் தேவம் மோதகம் தம்தமேவ ச ।
பக்தாபயப்ரதாதாரம் வம்தே விக்நவிநாஶநம் ।
ஓம் ஹரித்ரா கணபதயே நம꞉ ।
அஸ்மிந் ஹரித்ராபிம்பே ஶ்ரீமஹாகணபதிம் ஆவாஹயாமி, ஸ்தாபயாமி, பூஜயாமி ॥',
        'haridrābhaṃ caturbāhuṃ haridrāvadanaṃ prabhum ।
pāśāṃkuśadharaṃ devaṃ modakaṃ daṃtameva ca ।
bhaktā''bhayapradātāraṃ vaṃde vighnavināśanam ।
oṃ haridrā gaṇapataye namaḥ ।
asmin haridrābiṃbe śrīmahāgaṇapatiṃ āvāhayāmi, sthāpayāmi, pūjayāmi ॥',
        'I salute the remover of obstacles: turmeric-coloured and turmeric-faced, four-armed, holding the noose, the goad, the modaka and his tusk, who gives fearlessness to his devotees. Salutations to Haridra Ganapati. I invoke, install and worship Sri Mahaganapati in this turmeric image.',
        'Nine nights is a long undertaking for a household, and it begins the way every undertaking here begins: with Ganesha asked to go first. He is made from a pinch of turmeric because the point is not the image but the asking.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Haridra Ganapati invocation, as carried by the app for Varalakshmi');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 6, 'purvangam', '{main,punar,udvasana}', 'Sankalpam', 'ஸங்கல்பம்',
        'Take akshatai and a flower in the right hand and cover it with the left, resting both on the right thigh. Recite the day and place, then the resolve to worship Durga, Lakshmi and Saraswati. At the end, place the akshatai to the north and wash the hand. Say it again on every day of the nine.',
        'வலது கையில் அக்ஷதையும் புஷ்பமும் எடுத்து, இடது கையால் மூடி, வலது தொடையின் மேல் வைக்கவும். நாள், இடம் இவற்றைச் சொல்லி, துர்கா லக்ஷ்மீ ஸரஸ்வதீ பூஜை செய்வதாக ஸங்கல்பம் செய்யவும். முடிவில் அக்ஷதையை வடக்குப் பக்கம் போட்டுக் கையைக் கழுவவும். ஒன்பது நாட்களிலும் ஒவ்வொரு நாளும் இதைச் சொல்லவும்.',
        'मम उपात्त समस्त दुरितक्षय द्वारा श्री परमेश्वर प्रीत्यर्थं
शुभे शोभने मुहूर्ते आद्य ब्रह्मणः द्वितीय परार्धे श्वेत वराह कल्पे
वैवस्वत मन्वन्तरे अष्टाविंशतितमे कलियुगे प्रथमे पादे जम्बूद्वीपे
भरतवर्षे भरतखण्डे मेरोः दक्षिणे पार्श्वे अस्मिन् वर्तमाने व्यावहारिके
[DYNAMIC_PANCHANGAM_DATA]
अस्माकं सहकुटुम्बानां क्षेमस्थैर्यवीर्य-विजय-आयुरारोग्य ऐश्वर्याणां
अभिवृद्ध्यर्थं, समस्त मङ्गलावाप्त्यर्थं, समस्त दुरितोपशान्त्यर्थं,
श्री दुर्गा लक्ष्मी सरस्वती प्रसाद सिद्ध्यर्थं, श्री दुर्गा लक्ष्मी
सरस्वती पूजां करिष्ये। तदङ्गं कलश पूजां च करिष्ये।',
        'மம உபாத்த ஸமஸ்த துரிதக்ஷய த்வாரா ஶ்ரீ பரமேஶ்வர ப்ரீத்யர்தம்
ஶுபே ஶோபநே முஹூர்தே ஆத்ய ப்ரஹ்மண꞉ த்விதீய பரார்தே ஶ்வேத வராஹ கல்பே
வைவஸ்வத மந்வந்தரே அஷ்டாவிம்ஶதிதமே கலியுகே ப்ரதமே பாதே ஜம்பூத்வீபே
பரதவர்ஷே பரதகண்டே மேரோ꞉ தக்ஷிணே பார்ஶ்வே அஸ்மிந் வர்தமாநே வ்யாவஹாரிகே
[DYNAMIC_PANCHANGAM_DATA]
அஸ்மாகம் ஸஹகுடும்பாநாம் க்ஷேமஸ்தைர்யவீர்ய-விஜய-ஆயுராரோக்ய ஐஶ்வர்யாணாம்
அபிவ்ருத்த்யர்தம், ஸமஸ்த மங்கலாவாப்த்யர்தம், ஸமஸ்த துரிதோபஶாந்த்யர்தம்,
ஶ்ரீ துர்கா லக்ஷ்மீ ஸரஸ்வதீ ப்ரஸாத ஸித்த்யர்தம், ஶ்ரீ துர்கா லக்ஷ்மீ
ஸரஸ்வதீ பூஜாம் கரிஷ்யே। ததங்கம் கலஶ பூஜாம் ச கரிஷ்யே।',
        'mama upātta samasta duritakṣaya dvārā śrī parameśvara prītyarthaṃ
śubhe śobhane muhūrte ādya brahmaṇaḥ dvitīya parārdhe śveta varāha kalpe
vaivasvata manvantare aṣṭāviṃśatitame kaliyuge prathame pāde jambūdvīpe
bharatavarṣe bharatakhaṇḍe meroḥ dakṣiṇe pārśve asmin vartamāne vyāvahārike
[DYNAMIC_PANCHANGAM_DATA]
asmākaṃ sahakuṭumbānāṃ kṣemasthairyavīrya-vijaya-āyurārogya aiśvaryāṇāṃ
abhivṛddhyarthaṃ, samasta maṅgalāvāptyarthaṃ, samasta duritopaśāntyarthaṃ,
śrī durgā lakṣmī sarasvatī prasāda siddhyarthaṃ, śrī durgā lakṣmī
sarasvatī pūjāṃ kariṣye। tadaṅgaṃ kalaśa pūjāṃ ca kariṣye।',
        'For the removal of all my wrongs and for the pleasure of the Supreme Lord: at this auspicious moment, in the present age, on this day so described, for the welfare, steadiness, strength, victory, long life, health and prosperity of ourselves and our household, for every auspicious thing and the quieting of every ill, and to win the grace of Sri Durga, Lakshmi and Saraswati, I shall perform the worship of Sri Durga, Lakshmi and Saraswati, and as part of it the worship of the kalasham.',
        'One resolve, three goddesses. Navaratri is often told as three nights each of Durga, Lakshmi and Saraswati, but the sankalpam names all three together every day: what is being asked for is protection, prosperity and understanding at once, because a household needs all three at once.', 'all', true, true,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), p.286 pradhana sankalpa; frame and purposes from the common purvanga, p.13');

