       meaning_en, philosophy_en, philosophy_ta, gender_rule, variant_mantra_sanskrit,
       variant_note_en, false, scripts_generated,
       coalesce(source_ref || '; ', '') || 'shared purvangam, copied from ganesha_standard'
  from public.pooja_steps
 where pooja_id = 'ganesha_standard' and step_title_en = 'Ghanta Pooja';

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 9, 'pradhana', '{main}', 'Dhyanam', 'த்யானம்',
        'With akshatai and flowers in the hand, close the eyes and hold the form of the Goddess in mind: the slayer of Mahisha, riding the lion, threatening the demons. Then ask her into the kalasham or the image, and offer the flowers and akshatai. This is done on the first day.',
        'கையில் அக்ஷதையும் புஷ்பமும் வைத்துக்கொண்டு, கண்களை மூடி தேவியின் வடிவத்தை மனதில் நிறுத்தவும் — மஹிஷனை வதைத்தவள், ஸிம்ஹ வாஹினி, அஸுரர்களை அதட்டுபவள். பின் கலசத்திலோ விக்ரஹத்திலோ எழுந்தருளும்படி அழைத்து புஷ்பம் அக்ஷதை சமர்ப்பிக்கவும். இது முதல் நாளில் செய்யப்படுகிறது.',
        'महिषघ्नीं महादेवीं कुमारीं सिंहवाहिनीम्।
दानवांस्तर्जयन्तीम् च सर्वकामदुघां शिवाम्॥
ध्यायामि मनसा दुर्गां नाभिमध्ये व्यवस्थिताम्।
आगच्छ वरदे देवि दैत्यदर्पनिपातिनि॥
पूजां गृहाण सुमुखि नमस्ते शङ्करप्रिये।
सर्वतीर्थमयं वारि सर्वदेव समन्वितम्॥
इमं घटं समागच्छ तिष्ठ देवगणैस्सह।
दुर्गे देवि समागच्छ सान्निध्यं इह कल्पय॥
अस्मिन् कलशे(बिम्बे)श्रीदुर्गा लक्ष्मी सरस्वतीं ध्यायामि',
        'மஹிஷக்நீம் மஹாதேவீம் குமாரீம் ஸிம்ஹவாஹிநீம்।
தாநவாம்ஸ்தர்ஜயந்தீம் ச ஸர்வகாமதுகாம் ஶிவாம்॥
த்யாயாமி மநஸா துர்காம் நாபிமத்யே வ்யவஸ்திதாம்।
ஆகச்ச வரதே தேவி தைத்யதர்பநிபாதிநி॥
பூஜாம் க்ருஹாண ஸுமுகி நமஸ்தே ஶங்கரப்ரியே।
ஸர்வதீர்தமயம் வாரி ஸர்வதேவ ஸமந்விதம்॥
இமம் கடம் ஸமாகச்ச திஷ்ட தேவகணைஸ்ஸஹ।
துர்கே தேவி ஸமாகச்ச ஸாந்நித்யம் இஹ கல்பய॥
அஸ்மிந் கலஶே(பிம்பே)ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீம் த்யாயாமி',
        'mahiṣaghnīṃ mahādevīṃ kumārīṃ siṃhavāhinīm।
dānavāṃstarjayantīm ca sarvakāmadughāṃ śivām॥
dhyāyāmi manasā durgāṃ nābhimadhye vyavasthitām।
āgaccha varade devi daityadarpanipātini॥
pūjāṃ gṛhāṇa sumukhi namaste śaṅkarapriye।
sarvatīrthamayaṃ vāri sarvadeva samanvitam॥
imaṃ ghaṭaṃ samāgaccha tiṣṭha devagaṇaissaha।
durge devi samāgaccha sānnidhyaṃ iha kalpaya॥
asmin kalaśe(bimbe)śrīdurgā lakṣmī sarasvatīṃ dhyāyāmi',
        'Slayer of Mahisha, great Goddess, maiden riding the lion, who threatens the demons, auspicious one who yields every wish: I meditate on Durga, dwelling at the centre of my being. Come, giver of boons, who throws down the pride of demons; accept this worship, gracious one, beloved of Shankara. This water holds every sacred river and every god: come into this vessel and stay with the hosts of gods, Goddess Durga, and make yourself present here. In this kalasham I meditate on Sri Durga, Lakshmi and Saraswati.',
        'Nabhimadhye vyavasthitam, "dwelling at the centre". The Goddess is first found within and only then asked into the pot. The kalasham does not bring her; it gives the worship somewhere to face.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), p.286 dhyanam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 10, 'pradhana', '{main}', 'Avahanam', 'ஆவாஹனம்',
        'Invite the Goddess with folded hands and offer flowers and akshatai at the kalasham or image.',
        'கைகூப்பி தேவியை எழுந்தருளச் செய்து, கலசத்திலோ விக்ரஹத்திலோ புஷ்பம் அக்ஷதை சமர்ப்பிக்கவும்.',
        'एहि दुर्गे महाभागे रक्षार्थं मम सर्वदा।
आवाहयाम्यहं देवि सर्वकामार्थ सिद्धये॥
श्रीदुर्गा लक्ष्मी सरस्वतीं आवाहयामि',
        'ஏஹி துர்கே மஹாபாகே ரக்ஷார்தம் மம ஸர்வதா।
ஆவாஹயாம்யஹம் தேவி ஸர்வகாமார்த ஸித்தயே॥
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீம் ஆவாஹயாமி',
        'ehi durge mahābhāge rakṣārthaṃ mama sarvadā।
āvāhayāmyahaṃ devi sarvakāmārtha siddhaye॥
śrīdurgā lakṣmī sarasvatīṃ āvāhayāmi',
        'Come, Durga, most blessed, to protect me always. I invoke you, Goddess, for the accomplishment of every aim. I invoke Sri Durga, Lakshmi and Saraswati.',
        'Raksharthm mama sarvada, "to protect me always". Durga is invited first as a protector. The other two are named after her, in the same breath, because nothing grows in a house that is not safe.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), p.287 aavaahanam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 11, 'pradhana', '{main}', 'Prana Pratishtha', 'ப்ராண ப்ரதிஷ்டை',
        'Touch the kalasham or the image with the fingertips of the right hand and ask the life breath to settle in it. From now until Vijayadashami it is treated as present.',
        'வலது கை விரல் நுனிகளால் கலசத்தையோ விக்ரஹத்தையோ தொட்டு, உயிர்ப்பு அதில் நிலைபெறும்படி வேண்டவும். இனி விஜயதசமி வரை அது எழுந்தருளியிருப்பதாகவே கருதப்படுகிறது.',
        'ॐ असुनीते पुनरस्मासु चक्षुः
पुनः प्राणमिह नो धेहि भोगम् ।
ज्योक्पश्येम सूर्यमुच्चरन्त
मनुमते मृडया नः स्वस्ति ।
अमृतं वै प्राणा अमृतमापः
प्राणानेव यथास्थानमुपह्वयते ॥
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः ।
आवाहिता भव स्थापिता भव ।
सुप्रसन्ना भव वरदा भव ।
स्थिरासनं कुरु प्रसीद प्रसीद ।',
        'ஓம் அஸுநீதே புநரஸ்மாஸு சக்ஷு꞉
புந꞉ ப்ராணமிஹ நோ தேஹி போகம் ।
ஜ்யோக்பஶ்யேம ஸூர்யமுச்சரந்த
மநுமதே ம்ருடயா ந꞉ ஸ்வஸ்தி ।
அம்ருதம் வை ப்ராணா அம்ருதமாப꞉
ப்ராணாநேவ யதாஸ்தாநமுபஹ்வயதே ॥
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ ।
ஆவாஹிதா பவ ஸ்தாபிதா பவ ।
ஸுப்ரஸந்நா பவ வரதா பவ ।
ஸ்திராஸநம் குரு ப்ரஸீத ப்ரஸீத ।',
        'oṃ asunīte punarasmāsu cakṣuḥ
punaḥ prāṇamiha no dhehi bhogam ।
jyokpaśyema sūryamuccaranta
manumate mṛḍayā naḥ svasti ।
amṛtaṃ vai prāṇā amṛtamāpaḥ
prāṇāneva yathāsthānamupahvayate ॥
śrīdurgā lakṣmī sarasvatī devyai namaḥ ।
āvāhitā bhava sthāpitā bhava ।
suprasannā bhava varadā bhava ।
sthirāsanaṃ kuru prasīda prasīda ।',
        'Asuniti, giver of breath: give us back sight and breath and the enjoyment of life, so that we may long see the sun rise; Anumati, be kind and keep us well. Breath and water are both immortal, and so the breaths are called each to its place. Salutations to Sri Durga, Lakshmi and Saraswati: be invoked, be installed, be pleased, grant boons, take a steady seat, be gracious.',
        'For nine days the kalasham is a guest who does not leave in the evening. Prana Pratishtha is what makes the daily pooja on the days that follow a visit to someone already in the house, rather than an invitation repeated each morning.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Prana pratishtha as the common section prescribes (step 18), feminine forms as carried for Varalakshmi');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 12, 'pradhana', '{main,punar}', 'Asanam, Padyam, Arghyam & Achamaniyam', 'ஆஸனம், பாத்யம், அர்க்யம் & ஆசமனீயம்',
        'A seat first: offer flowers and akshatai. Then water for the feet, water for the hands with akshatai, sandal and a flower in it, and scented water to sip. Pour each from the uddharani into the plate.',
        'முதலில் ஆஸனம் — புஷ்பம் அக்ஷதை சமர்ப்பிக்கவும். பின் பாதம் கழுவ ஜலம், அக்ஷதை சந்தனம் புஷ்பம் கலந்த அர்க்ய ஜலம், பருக வாசனை ஜலம். ஒவ்வொன்றையும் உத்தரிணியால் தாம்பாளத்தில் விடவும்.',
        'अनेकरत्न संयुक्तं नानामणिगणान्वितम्।
कार्तस्वरमयं दिव्यमासनं प्रतिगृह्यताम्॥
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः आसनं समर्पयामि
गङ्गादि सर्व तीर्थेभ्यो मया प्रार्थनयाहृतम्।
तोयमेतत् सुखस्पर्शं पाद्यार्थं प्रतिगृह्यताम्॥
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः पाद्यं समर्पयामि
निधीनां सर्वरत्नानां त्वं अनर्घ्यगुणाह्यसि।
सिंहोपरिस्थिते देवि गृहाणार्घ्यं नमोऽस्तु ते॥
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः अर्घ्यं समर्पयामि
कर्पूरेण सुगन्धेन सुरभि स्वादु शीतलम्।
तोयमाचमनीयार्थं देवि त्वं प्रतिगृह्यताम्॥
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः आचमनीयं समर्पयामि',
        'அநேகரத்ந ஸம்யுக்தம் நாநாமணிகணாந்விதம்।
கார்தஸ்வரமயம் திவ்யமாஸநம் ப்ரதிக்ருஹ்யதாம்॥
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ ஆஸநம் ஸமர்பயாமி
கங்காதி ஸர்வ தீர்தேப்யோ மயா ப்ரார்தநயாஹ்ருதம்।
தோயமேதத் ஸுகஸ்பர்ஶம் பாத்யார்தம் ப்ரதிக்ருஹ்யதாம்॥
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ பாத்யம் ஸமர்பயாமி
நிதீநாம் ஸர்வரத்நாநாம் த்வம் அநர்க்யகுணாஹ்யஸி।
ஸிம்ஹோபரிஸ்திதே தேவி க்ருஹாணார்க்யம் நமோஸ்து தே॥
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ அர்க்யம் ஸமர்பயாமி
கர்பூரேண ஸுகந்தேந ஸுரபி ஸ்வாது ஶீதலம்।
தோயமாசமநீயார்தம் தேவி த்வம் ப்ரதிக்ருஹ்யதாம்॥
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ ஆசமநீயம் ஸமர்பயாமி',
        'anekaratna saṃyuktaṃ nānāmaṇigaṇānvitam।
kārtasvaramayaṃ divyamāsanaṃ pratigṛhyatām॥
śrīdurgā lakṣmī sarasvatī devyai namaḥ āsanaṃ samarpayāmi
gaṅgādi sarva tīrthebhyo mayā prārthanayāhṛtam।
toyametat sukhasparśaṃ pādyārthaṃ pratigṛhyatām॥
śrīdurgā lakṣmī sarasvatī devyai namaḥ pādyaṃ samarpayāmi
nidhīnāṃ sarvaratnānāṃ tvaṃ anarghyaguṇāhyasi।
siṃhoparisthite devi gṛhāṇārghyaṃ namo''stu te॥
śrīdurgā lakṣmī sarasvatī devyai namaḥ arghyaṃ samarpayāmi
karpūreṇa sugandhena surabhi svādu śītalam।
toyamācamanīyārthaṃ devi tvaṃ pratigṛhyatām॥
śrīdurgā lakṣmī sarasvatī devyai namaḥ ācamanīyaṃ samarpayāmi',
        'Receive this divine golden seat, set with many jewels and gems. Water brought at my request from the Ganga and every holy river, pleasant to the touch: receive it for your feet. Among all treasures and jewels you are beyond price, Goddess seated on the lion: receive this arghyam, salutations to you. Cool, sweet water, fragrant with camphor: receive it to sip.',
        'Simhoparisthite, "seated on the lion". The verses never lose sight of who is being received: even the water for the hands is offered to the Goddess on her mount, not to an abstract presence.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), pp.288-289');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 13, 'pradhana', '{main,punar}', 'Snanam', 'ஸ்நானம்',
        'Sprinkle water over the kalasham or image with a flower. If the image can be bathed, bathe it; a dressed kalasham is only sprinkled.',
        'புஷ்பத்தால் கலசத்தின் மேல் அல்லது விக்ரஹத்தின் மேல் ஜலம் தெளிக்கவும். விக்ரஹத்தை அபிஷேகம் செய்ய முடிந்தால் செய்யவும்; அலங்கரித்த கலசத்திற்கு ப்ரோக்ஷணம் மட்டும்.',
        'मन्दाकिन्याः समानीतैर्हेमाम्भोरुहवासितैः।
स्नानं कुरुष्व देवेशि सलिलैश्च सुगन्धिभिः॥
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः स्नानं समर्पयामि',
        'மந்தாகிந்யா꞉ ஸமாநீதைர்ஹேமாம்போருஹவாஸிதை꞉।
ஸ்நாநம் குருஷ்வ தேவேஶி ஸலிலைஶ்ச ஸுகந்திபி꞉॥
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ ஸ்நாநம் ஸமர்பயாமி',
        'mandākinyāḥ samānītairhemāmbhoruhavāsitaiḥ।
snānaṃ kuruṣva deveśi salilaiśca sugandhibhiḥ॥
śrīdurgā lakṣmī sarasvatī devyai namaḥ snānaṃ samarpayāmi',
        'Bathe, Queen of the gods, in fragrant water brought from the Mandakini and scented with golden lotuses.',
        'Mandakini is the Ganga as it flows in heaven. The water in the uddharani is whatever the tap gave this morning; the verse says what it is being treated as, and the treating is the rite.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), p.289');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 14, 'pradhana', '{main,punar}', 'Vastram & Upaveetam', 'வஸ்த்ரம் & உபவீதம்',
        'Offer a pair of new cloths with a blouse piece, or drape a cloth on the kalasham. Then offer the sacred thread, or akshatai in its place.',
        'ரவிக்கைத் துணியுடன் இரண்டு புதிய வஸ்திரங்களைச் சமர்ப்பிக்கவும், அல்லது கலசத்திற்கு ஒரு துணி சாற்றவும். பின் உபவீதம் — இல்லையெனில் அதற்குப் பதில் அக்ஷதை.',
        'पट्टकूलयुगं देवि कञ्चुकेन समन्वितम्।
परिधेहि कृपां कृत्वा दुर्गे दुर्गतिनाशिनि॥
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः वस्त्रयुग्मं समर्पयामि
स्वर्णसूत्रमयं दिव्यं ब्रह्मणा निर्मितं पुरा।
उपवीतं मया दत्तं गृहाण परमेश्वरि॥
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः उपवीतं समर्पयामि',
        'பட்டகூலயுகம் தேவி கஞ்சுகேந ஸமந்விதம்।
பரிதேஹி க்ருபாம் க்ருத்வா துர்கே துர்கதிநாஶிநி॥
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ வஸ்த்ரயுக்மம் ஸமர்பயாமி
ஸ்வர்ணஸூத்ரமயம் திவ்யம் ப்ரஹ்மணா நிர்மிதம் புரா।
உபவீதம் மயா தத்தம் க்ருஹாண பரமேஶ்வரி॥
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ உபவீதம் ஸமர்பயாமி',
        'paṭṭakūlayugaṃ devi kañcukena samanvitam।
paridhehi kṛpāṃ kṛtvā durge durgatināśini॥
śrīdurgā lakṣmī sarasvatī devyai namaḥ vastrayugmaṃ samarpayāmi
svarṇasūtramayaṃ divyaṃ brahmaṇā nirmitaṃ purā।
upavītaṃ mayā dattaṃ gṛhāṇa parameśvari॥
śrīdurgā lakṣmī sarasvatī devyai namaḥ upavītaṃ samarpayāmi',
        'A pair of silk cloths with a bodice: put them on, Goddess, out of kindness, Durga who destroys misfortune. This divine thread of golden strands, made by Brahma long ago: accept the sacred thread I give, Supreme Goddess.',
        'Durgatinashini, "destroyer of misfortune", is a play on her name: Durga is the one who carries you across what is durga, hard to cross. The epithet turns up at the moment she is being dressed, as a guest is, for the days she is staying.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), pp.289-290');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 15, 'pradhana', '{main,punar}', 'Gandham, Mangala Dravyam & Abharanam', 'கந்தம், மங்கள த்ரவ்யம் & ஆபரணம்',
        'Offer sandal paste, then turmeric, kumkumam and kanmai (kajal) one by one, then ornaments: a bangle, a chain, whatever the house sets aside for her.',
        'சந்தனம் சமர்ப்பித்து, பின் ஒவ்வொன்றாக மஞ்சள், குங்குமம், கண்மை சமர்ப்பிக்கவும்; பின் ஆபரணங்கள் — வளையல், சங்கிலி, அவளுக்கென்று வைத்திருப்பது எதுவோ அது.',
        'श्रीखण्डचन्दनं दिव्यं गन्धाढ्यं सुमनोहरम्।
विलेपनं च देवेशि चन्दनं प्रतिगृह्यताम्॥
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः गन्धान् धारयामि
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः सौभाग्यद्रव्याणि समर्पयामि
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः कुङ्कुमं समर्पयामि
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः कज्जलं समर्पयामि
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः आभरणानि समर्पयामि',
        'ஶ்ரீகண்டசந்தநம் திவ்யம் கந்தாட்யம் ஸுமநோஹரம்।
விலேபநம் ச தேவேஶி சந்தநம் ப்ரதிக்ருஹ்யதாம்॥
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ கந்தாந் தாரயாமி
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ ஸௌபாக்யத்ரவ்யாணி ஸமர்பயாமி
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ குங்குமம் ஸமர்பயாமி
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ கஜ்ஜலம் ஸமர்பயாமி
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ ஆபரணாநி ஸமர்பயாமி',
        'śrīkhaṇḍacandanaṃ divyaṃ gandhāḍhyaṃ sumanoharam।
vilepanaṃ ca deveśi candanaṃ pratigṛhyatām॥
śrīdurgā lakṣmī sarasvatī devyai namaḥ gandhān dhārayāmi
śrīdurgā lakṣmī sarasvatī devyai namaḥ saubhāgyadravyāṇi samarpayāmi
śrīdurgā lakṣmī sarasvatī devyai namaḥ kuṅkumaṃ samarpayāmi
śrīdurgā lakṣmī sarasvatī devyai namaḥ kajjalaṃ samarpayāmi
śrīdurgā lakṣmī sarasvatī devyai namaḥ ābharaṇāni samarpayāmi',
        'Divine sandal paste, rich in fragrance and lovely: receive it as an ointment, Queen of the gods. Salutations to Sri Durga, Lakshmi and Saraswati: I offer the auspicious articles of a married woman, kumkumam, kajal and ornaments.',
        'Turmeric, kumkumam and kajal are saubhagya dravyas, the marks of a woman whose household is whole. They are offered to the Goddess for the same reason the sumangalis who visit during these nine days are given them on the way out.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), p.290');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 16, 'pradhana', '{main,punar}', 'Akshatai & Pushpam', 'அக்ஷதை & புஷ்பம்',
        'Offer akshatai, then a garland, then loose flowers.',
        'அக்ஷதை சமர்ப்பித்து, பின் மாலையும் உதிரிப் புஷ்பமும் சமர்ப்பிக்கவும்.',
        'अक्षतान् निर्मलान् शुद्धान् मुक्तामणिसमन्वितान्।
गृहाणेमान् महादेवि देहि मे निर्मलां धियम्॥
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः अक्षतान् समर्पयामि
पद्मशङ्खज पुष्पादि शतपत्रैर्विचित्रिताम्।
पुष्पमालां प्रयच्छामि गृहाण त्वं सुरेश्वरि॥
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः
पुष्पमालां समर्पयामि। पुष्पैः पूजयामि।',
        'அக்ஷதாந் நிர்மலாந் ஶுத்தாந் முக்தாமணிஸமந்விதாந்।
க்ருஹாணேமாந் மஹாதேவி தேஹி மே நிர்மலாம் தியம்॥
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ அக்ஷதாந் ஸமர்பயாமி
பத்மஶங்கஜ புஷ்பாதி ஶதபத்ரைர்விசித்ரிதாம்।
புஷ்பமாலாம் ப்ரயச்சாமி க்ருஹாண த்வம் ஸுரேஶ்வரி॥
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉
புஷ்பமாலாம் ஸமர்பயாமி। புஷ்பை꞉ பூஜயாமி।',
        'akṣatān nirmalān śuddhān muktāmaṇisamanvitān।
gṛhāṇemān mahādevi dehi me nirmalāṃ dhiyam॥
śrīdurgā lakṣmī sarasvatī devyai namaḥ akṣatān samarpayāmi
padmaśaṅkhaja puṣpādi śatapatrairvicitritām।
puṣpamālāṃ prayacchāmi gṛhāṇa tvaṃ sureśvari॥
śrīdurgā lakṣmī sarasvatī devyai namaḥ
puṣpamālāṃ samarpayāmi। puṣpaiḥ pūjayāmi।',
        'Unbroken grains, spotless and pure, set with pearls and gems: receive them, great Goddess, and give me a spotless mind. A garland made with lotus and other flowers of a hundred petals: I offer it, receive it, Queen of the gods.',
        'Dehi me nirmalam dhiyam, "give me a spotless mind". The one request tucked into the upacharas is not for wealth or safety but for clear thinking, which is Saraswati being asked for in the middle of a Durga verse.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), p.291');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 17, 'pradhana', '{main,punar}', 'Anga Pooja', 'அங்க பூஜை',
        'Eighteen names, each with a limb, from the feet up to the head and then the whole body. Offer a flower or a pinch of akshatai at each.',
        'பதினெட்டு நாமங்கள், ஒவ்வொன்றும் ஒரு அங்கத்துடன், பாதம் முதல் சிரசு வரை, கடைசியில் முழு உடல். ஒவ்வொன்றிலும் ஒரு புஷ்பமோ சிறிது அக்ஷதையோ சமர்ப்பிக்கவும்.',
        null,
        null,
        null,
        'Eighteen names of the Goddess, each offered to a limb from the feet upward: Durga at the feet, Mahakali at the ankles, Kamalavasini at the navel, Maheshvari at the head, and Katyayani for the whole body.',
        'The names move between her fierce and gentle forms as they climb, Kali at the ankles and Kamalavasini, the lotus-dweller, at the navel. The anga pooja does not pick one aspect of the Goddess; it covers her from foot to head with all of them.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), pp.291-292');

insert into public.archana_items
  (pooja_step_id, seq, invoked_name_deva, invoked_name_ta, invoked_name_translit,
   offering_deva, offering_en, offering_ta)
values
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 17), 1, 'ॐ दुर्गायै नमः', 'ஓம் துர்காயை நம꞉', 'oṃ durgāyai namaḥ', 'पादौ पूजयामि', 'Worship the feet', 'பாதௌ பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 17), 2, 'ॐ महाकाल्यै नमः', 'ஓம் மஹாகால்யை நம꞉', 'oṃ mahākālyai namaḥ', 'गुल्फौ पूजयामि', 'Worship the ankle', 'குல்பௌ பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 17), 3, 'ॐ मंगलायै नमः', 'ஓம் மம்கலாயை நம꞉', 'oṃ maṃgalāyai namaḥ', 'जानुनी पूजयामि', 'Worship the knee', 'ஜாநுநீ பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 17), 4, 'ॐ कात्यायन्यै नमः', 'ஓம் காத்யாயந்யை நம꞉', 'oṃ kātyāyanyai namaḥ', 'ऊरू पूजयामि', 'Worship the thigh', 'ஊரூ பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 17), 5, 'ॐ भद्रकाल्यै नमः', 'ஓம் பத்ரகால்யை நம꞉', 'oṃ bhadrakālyai namaḥ', 'कटिं पूजयामि', 'Worship the waist', 'கடிம் பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 17), 6, 'ॐ कमलवासिन्यै नमः', 'ஓம் கமலவாஸிந்யை நம꞉', 'oṃ kamalavāsinyai namaḥ', 'नाभिं पूजयामि', 'Worship the navel', 'நாபிம் பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 17), 7, 'ॐ शिवायै नमः', 'ஓம் ஶிவாயை நம꞉', 'oṃ śivāyai namaḥ', 'उदरं पूजयामि', 'Worship the stomach', 'உதரம் பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 17), 8, 'ॐ क्षमायै नमः', 'ஓம் க்ஷமாயை நம꞉', 'oṃ kṣamāyai namaḥ', 'हृदयं पूजयामि', 'Worship the heart', 'ஹ்ருதயம் பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 17), 9, 'ॐ कौमार्यै नमः', 'ஓம் கௌமார்யை நம꞉', 'oṃ kaumāryai namaḥ', 'स्तनौ पूजयामि', 'Worship the breasts', 'ஸ்தநௌ பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 17), 10, 'ॐ उमायै नमः', 'ஓம் உமாயை நம꞉', 'oṃ umāyai namaḥ', 'हस्तौ पूजयामि', 'Worship the hands', 'ஹஸ்தௌ பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 17), 11, 'ॐ महागौर्यै नमः', 'ஓம் மஹாகௌர்யை நம꞉', 'oṃ mahāgauryai namaḥ', 'दक्षिणबाहुं पूजयामि', 'Worship the right arm', 'தக்ஷிணபாஹும் பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 17), 12, 'ॐ वैष्णव्यै नमः', 'ஓம் வைஷ்ணவ்யை நம꞉', 'oṃ vaiṣṇavyai namaḥ', 'वामबाहुं पूजयामि', 'Worship the left arm', 'வாமபாஹும் பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 17), 13, 'ॐ रमायै नमः', 'ஓம் ரமாயை நம꞉', 'oṃ ramāyai namaḥ', 'स्कन्धौ पूजयामि', 'Worship the shoulders', 'ஸ்கந்தௌ பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 17), 14, 'ॐ स्कन्दमात्रे नमः', 'ஓம் ஸ்கந்தமாத்ரே நம꞉', 'oṃ skandamātre namaḥ', 'कण्ठं पूजयामि', 'Worship the neck', 'கண்டம் பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 17), 15, 'ॐ महिषमर्दिन्यै नमः', 'ஓம் மஹிஷமர்திந்யை நம꞉', 'oṃ mahiṣamardinyai namaḥ', 'नेत्रे पूजयामि', 'Worship the eyes', 'நேத்ரே பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 17), 16, 'ॐ सिंहवाहिन्यै नमः', 'ஓம் ஸிம்ஹவாஹிந்யை நம꞉', 'oṃ siṃhavāhinyai namaḥ', 'मुखं पूजयामि', 'Worship the face', 'முகம் பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 17), 17, 'ॐ माहेश्वर्यै नमः', 'ஓம் மாஹேஶ்வர்யை நம꞉', 'oṃ māheśvaryai namaḥ', 'शिरः पूजयामि', 'Worship the head', 'ஶிர꞉ பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 17), 18, 'ॐ कात्यायन्यै नमः', 'ஓம் காத்யாயந்யை நம꞉', 'oṃ kātyāyanyai namaḥ', 'सर्वाण्यंगानि पूजयामि', 'Worship the whole body', 'ஸர்வாண்யம்காநி பூஜயாமி');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 18, 'pradhana', '{main,punar,udvasana}', 'Durga Ashtottara Shatanamavali', 'துர்கா அஷ்டோத்தர ஶதநாமாவளி',
        'Offer a flower or a pinch of akshatai at each of the hundred and eight names of Durga. On Vijayadashami these names are recited again before the Goddess is released.',
        'துர்கையின் நூற்றெட்டு நாமங்களில் ஒவ்வொன்றிலும் ஒரு புஷ்பமோ சிறிது அக்ஷதையோ சமர்ப்பிக்கவும். விஜயதசமியன்று தேவியை யதாஸ்தானம் செய்வதற்கு முன் இந்த நாமங்கள் மீண்டும் சொல்லப்படுகின்றன.',
        null,
        null,
        null,
        'One hundred and eight names of Durga, opening with Shri, Uma and Bharati and closing with Durgaparameshvari, the supreme Durga. Many are names of Lakshmi and Saraswati as well, which is the point of saying them at Navaratri.',
        'The list begins with shriyai, the name of Lakshmi, and keeps returning to names of learning and speech. A hundred and eight names of Durga turn out to hold all three goddesses of the sankalpam.', 'all', true, false,
        'durga_ashtottara_108', 'Sampradaya Vratha Pooja Vidhi (Giri), pp.293-296, count markers verified in both scripts');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 19, 'pradhana', '{main,punar}', 'Lakshmi Ashtottara Shatanamavali', 'லக்ஷ்மி அஷ்டோத்தர ஶதநாமாவளி',
        'The hundred and eight names of Lakshmi follow the names of Durga. Offer a flower or akshatai at each. On a short day this and the next list may be left for the middle three days, when Lakshmi is especially worshipped.',
        'துர்கா நாமங்களைத் தொடர்ந்து லக்ஷ்மியின் நூற்றெட்டு நாமங்கள். ஒவ்வொன்றிலும் புஷ்பமோ அக்ஷதையோ சமர்ப்பிக்கவும். நேரம் குறைவான நாளில், லக்ஷ்மிக்கு உரிய நடு மூன்று நாட்களுக்கு இதை விட்டு வைக்கலாம்.',
        null,
        null,
        null,
        'One hundred and eight names of Lakshmi, beginning with Prakriti and Vikriti, nature and its transformation, and closing with Bhuvaneshvari, mistress of the worlds.',
        'The Durga list is followed by the lists of the other two goddesses the sankalpam named, so that each of the three is addressed by her own names as well as together.', 'all', true, false,
        'lakshmi_ashtottara_108', 'Sampradaya Vratha Pooja Vidhi (Giri), p.296 rubric: Lakshmi ashtottaram, as carried for Varalakshmi');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 20, 'pradhana', '{main,punar}', 'Saraswati Ashtottara Shatanamavali', 'ஸரஸ்வதீ அஷ்டோத்தர ஶதநாமாவளி',
        'Then the hundred and eight names of Saraswati, with a flower or akshatai at each. They are the same names said over the books on Saraswati Pooja.',
        'பின் ஸரஸ்வதியின் நூற்றெட்டு நாமங்கள், ஒவ்வொன்றிலும் புஷ்பமோ அக்ஷதையோ. ஸரஸ்வதீ பூஜையன்று புத்தகங்களின் மேல் சொல்லப்படும் அதே நாமங்கள் இவை.',
        null,
        null,
        null,
        'One hundred and eight names of Saraswati, opening with Saraswati and Mahabhadra and closing with Brahmavishnushivatmika, she who is the self of Brahma, Vishnu and Shiva.',
        'The last of the three lists ends by naming her as the self of the whole trinity, which is a fitting place for a Navaratri archana to stop.', 'all', true, false,
        'saraswati_ashtottara_108', 'Sampradaya Vratha Pooja Vidhi (Giri), p.296 rubric: Saraswati ashtottaram, pp.315-318');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 21, 'uttara', '{main,punar,udvasana}', 'Dhoopam & Deepam', 'தூபம் & தீபம்',
        'Light the incense and wave it before the Goddess, then wave the ghee lamp. Ring the bell through both, then offer a spoon of water.',
        'ஊதுபத்தியை ஏற்றி தேவியின் முன் காட்டவும், பின் நெய் தீபம் காட்டவும். இரண்டின் போதும் மணி அடிக்கவும்; பின் ஒரு ஸ்பூன் ஜலம் சமர்ப்பிக்கவும்.',
        'दशाङ्गं गुग्गुलोपेतं चन्दनागरु संयुतम्।
समर्पितं मया भक्त्या महादेवि प्रतिगृह्यताम्।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः धूपं आघ्रापयामि ।
साज्यं त्रिवर्त्तिसंयुक्तं महातेजो महोज्वलम्।
दीपं दास्यामि देवेशि सुप्रीता भव सर्वदा।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः दीपं दर्शयामि
धूप,दीपानन्तरं आचमनीयं समर्पयामि ।',
        'தஶாங்கம் குக்குலோபேதம் சந்தநாகரு ஸம்யுதம்।
ஸமர்பிதம் மயா பக்த்யா மஹாதேவி ப்ரதிக்ருஹ்யதாம்।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ தூபம் ஆக்ராபயாமி ।
ஸாஜ்யம் த்ரிவர்த்திஸம்யுக்தம் மஹாதேஜோ மஹோஜ்வலம்।
தீபம் தாஸ்யாமி தேவேஶி ஸுப்ரீதா பவ ஸர்வதா।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ தீபம் தர்ஶயாமி
தூப,தீபாநந்தரம் ஆசமநீயம் ஸமர்பயாமி ।',
        'daśāṅgaṃ guggulopetaṃ candanāgaru saṃyutam।
samarpitaṃ mayā bhaktyā mahādevi pratigṛhyatām।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ dhūpaṃ āghrāpayāmi ।
sājyaṃ trivarttisaṃyuktaṃ mahātejo mahojvalam।
dīpaṃ dāsyāmi deveśi suprītā bhava sarvadā।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ dīpaṃ darśayāmi
dhūpa,dīpānantaraṃ ācamanīyaṃ samarpayāmi ।',
        'Incense of ten ingredients with guggulu, sandal and aloe, offered with devotion: receive it, great Goddess. A lamp with ghee and three wicks, of great brilliance and blaze: I give it to you, Queen of the gods; be pleased always. After incense and lamp, I offer water to sip.',
        'Trivarti, "three wicks". The lamp offered to the three goddesses has a wick for each of them, which is why a Navaratri lamp is so often a three-wick one.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), p.297');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 22, 'uttara', '{main,punar,udvasana}', 'Naivedyam & Tambulam', 'நைவேத்யம் & தாம்பூலம்',
        'Set the food on a plate or a plantain leaf on a cleaned spot in front. Sprinkle water on it with the vyahritis, say the Gayatri, and circle water around it three times. Offer water as its bed, then gesture as if feeding at each svaha. Name the offering, water between, water to rinse, and finally betel leaves and areca nut sprinkled with water. In the evening the sprinkling line is said the other way round: ritam tva satyena parishinchami.',
        'சுத்தம் செய்த இடத்தில் தட்டிலோ வாழையிலையிலோ நைவேத்யத்தை வைக்கவும். வ்யாஹ்ருதிகளுடன் ஜலம் தெளித்து, காயத்ரீ சொல்லி, மூன்று முறை ஜலத்தால் சுற்றவும். அம்ருதோபஸ்தரணமாக ஜலம் விட்டு, ஒவ்வொரு ஸ்வாஹாவிற்கும் ஊட்டுவது போல் கை காட்டவும். நைவேத்யத்தைச் சொல்லி, நடுவில் ஜலம், பின் ஆசமனம், கடைசியில் ஜலம் தெளித்த வெற்றிலை பாக்கு. மாலையில் தெளிக்கும் வரி மாற்றிச் சொல்லப்படும்: ருதம் த்வா ஸத்யேன பரிஷிஞ்சாமி.',
        'ॐ भूर्भुवस्सुवः
तत्सवितुर्वरेण्यं भर्गोदेवस्य धीमहि, धियो यो नः प्रचोदयात्
देवसवितः प्रसुव। सत्यं त्वर्तेन परिषिञ्चामि।
अमृतोपस्तरणमसि ।
ॐ प्राणाय स्वाहा, ॐ अपानाय स्वाहा, ॐ व्यानाय स्वाहा,
ॐ उदानाय स्वाहा, ॐ समानाय स्वाहा, ॐ ब्रह्मणे स्वाहा।
अन्नम् चतुर्विधं स्वादु षड्रसैः सुसमन्वितम्।
नैवेद्यं गृह्यतां देवि भक्तिं मे ह्यचलां कुरु।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः महानैवेद्यं निवेदयामि
मध्ये मध्ये अमृतपानीयं समर्पयामि ।
निवेदनानन्तरं आचमनीयं समर्पयामि ।
एलालवङ्ग कस्तूरी कर्पूरैः पुण्यवासितम्।
वीटिकां मुखवासार्थं अर्पयामि सुरेश्वरि।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः कर्पूरताम्बूलं समर्पयामि।।',
        'ஓம் பூர்புவஸ்ஸுவ꞉
தத்ஸவிதுர்வரேண்யம் பர்கோதேவஸ்ய தீமஹி, தியோ யோ ந꞉ ப்ரசோதயாத்
தேவஸவித꞉ ப்ரஸுவ। ஸத்யம் த்வர்தேந பரிஷிஞ்சாமி।
அம்ருதோபஸ்தரணமஸி ।
ஓம் ப்ராணாய ஸ்வாஹா, ஓம் அபாநாய ஸ்வாஹா, ஓம் வ்யாநாய ஸ்வாஹா,
ஓம் உதாநாய ஸ்வாஹா, ஓம் ஸமாநாய ஸ்வாஹா, ஓம் ப்ரஹ்மணே ஸ்வாஹா।
அந்நம் சதுர்விதம் ஸ்வாது ஷட்ரஸை꞉ ஸுஸமந்விதம்।
நைவேத்யம் க்ருஹ்யதாம் தேவி பக்திம் மே ஹ்யசலாம் குரு।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ மஹாநைவேத்யம் நிவேதயாமி
மத்யே மத்யே அம்ருதபாநீயம் ஸமர்பயாமி ।
நிவேதநாநந்தரம் ஆசமநீயம் ஸமர்பயாமி ।
ஏலாலவங்க கஸ்தூரீ கர்பூரை꞉ புண்யவாஸிதம்।
வீடிகாம் முகவாஸார்தம் அர்பயாமி ஸுரேஶ்வரி।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ கர்பூரதாம்பூலம் ஸமர்பயாமி।।',
        'oṃ bhūrbhuvassuvaḥ
tatsaviturvareṇyaṃ bhargodevasya dhīmahi, dhiyo yo naḥ pracodayāt
devasavitaḥ prasuva। satyaṃ tvartena pariṣiñcāmi।
amṛtopastaraṇamasi ।
oṃ prāṇāya svāhā, oṃ apānāya svāhā, oṃ vyānāya svāhā,
oṃ udānāya svāhā, oṃ samānāya svāhā, oṃ brahmaṇe svāhā।
annam caturvidhaṃ svādu ṣaḍrasaiḥ susamanvitam।
naivedyaṃ gṛhyatāṃ devi bhaktiṃ me hyacalāṃ kuru।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ mahānaivedyaṃ nivedayāmi
madhye madhye amṛtapānīyaṃ samarpayāmi ।
nivedanānantaraṃ ācamanīyaṃ samarpayāmi ।
elālavaṅga kastūrī karpūraiḥ puṇyavāsitam।
vīṭikāṃ mukhavāsārthaṃ arpayāmi sureśvari।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ karpūratāmbūlaṃ samarpayāmi।।',
        'Om bhur bhuvah suvah. We meditate on the glorious light of the divine Savitr; may it inspire our minds. Divine Savitr, impel: I sprinkle you, truth, with order. You are the immortal bed. To the five breaths and to Brahman, hail. Food of four kinds, sweet and full of the six tastes: receive this offering, Goddess, and make my devotion unshakeable. Water between mouthfuls; water to rinse after the meal. A betel roll scented with cardamom, clove, musk and camphor, to sweeten the mouth: I offer it, Queen of the gods.',
        'Bhaktim me hyachalam kuru, "make my devotion unshakeable". The one thing asked in return for the meal is not a favour but steadiness, which over nine days of the same pooja is the thing most likely to run out.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), pp.298-299');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 23, 'uttara', '{udvasana}', 'Karpura Neerajanam', 'கற்பூர நீராஜனம்',
        'Before the Goddess is sent home, light camphor and wave it three times clockwise before the kalasham or image, ringing the bell. Then offer a spoon of water.',
        'தேவிக்கு விடை கொடுப்பதற்கு முன், கற்பூரம் ஏற்றி கலசத்தின் அல்லது விக்ரஹத்தின் முன் மூன்று முறை வலமாகச் சுற்றிக் காட்டவும், மணி அடித்தபடி. பின் ஒரு ஸ்பூன் ஜலம் சமர்ப்பிக்கவும்.',
        'कृतवर्ति सहस्रैश्च कर्पूर शकलैस्तदा।
नीराजनं मया दत्तं गृहाण वरदा भव ।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः कर्पूरनीराजनं दर्शयामि।।
नीराजनानन्तरं आचमनीयं समर्पयामि',
        'க்ருதவர்தி ஸஹஸ்ரைஶ்ச கர்பூர ஶகலைஸ்ததா।
நீராஜநம் மயா தத்தம் க்ருஹாண வரதா பவ ।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ கர்பூரநீராஜநம் தர்ஶயாமி।।
நீராஜநாநந்தரம் ஆசமநீயம் ஸமர்பயாமி',
        'kṛtavarti sahasraiśca karpūra śakalaistadā।
nīrājanaṃ mayā dattaṃ gṛhāṇa varadā bhava ।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ karpūranīrājanaṃ darśayāmi।।
nīrājanānantaraṃ ācamanīyaṃ samarpayāmi',
        'Lit with a thousand wicks and pieces of camphor, this waving of light is offered by me: receive it and be a giver of boons. Salutations to Sri Durga, Lakshmi and Saraswati: I show the camphor flame. After it, I offer water to sip.',
        'On the last morning the camphor is the final light the Goddess is shown in this house. It burns out completely and leaves nothing behind, which is the right thing to wave just before asking her to go and to come again.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), p.304 rubric for dashami (wave camphor); verse from pp.321-322, addressed to the same three goddesses');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 24, 'uttara', '{main,punar,udvasana}', 'Pushpanjali', 'புஷ்பாஞ்ஜலி',
        'Take flowers and akshatai in both cupped hands, recite, and offer them at her feet. Everyone present may offer flowers.',
        'இரு கைகளையும் குவித்து புஷ்பமும் அக்ஷதையும் எடுத்து, ஸ்லோகம் சொல்லி அவள் பாதத்தில் சமர்ப்பிக்கவும். அங்கிருக்கும் அனைவரும் புஷ்பம் சமர்ப்பிக்கலாம்.',
        'मन्दार पारिजातादि पाटली केतकानि च।
जाती चंपक पुष्पाणि गृहाणेमानि शोभने।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः पुष्पाञ्जलिं समर्पयामि।।',
        'மந்தார பாரிஜாதாதி பாடலீ கேதகாநி ச।
ஜாதீ சம்பக புஷ்பாணி க்ருஹாணேமாநி ஶோபநே।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ புஷ்பாஞ்ஜலிம் ஸமர்பயாமி।।',
        'mandāra pārijātādi pāṭalī ketakāni ca।
jātī caṃpaka puṣpāṇi gṛhāṇemāni śobhane।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ puṣpāñjaliṃ samarpayāmi।।',
        'Mandara, parijata, patali and ketaki, jasmine and champaka: receive these flowers, radiant one.',
        'The only step of the pooja that is handed to everyone in the room. Navaratri is a household festival with guests coming and going, and the flowers are how the visitors take part in the worship rather than watching it.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), p.299');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 25, 'uttara', '{main,punar,udvasana}', 'Pradakshina & Namaskaram', 'ப்ரதக்ஷிணம் & நமஸ்காரம்',
        'Go round the Goddess clockwise with palms joined, or turn in place where you stand, then prostrate.',
        'கைகூப்பி தேவியை வலமாகச் சுற்றவும், அல்லது நின்ற இடத்திலேயே சுற்றவும்; பின் நமஸ்காரம் செய்யவும்.',
        'दुर्गे स्मृता हरसि भीतिमशेष-जन्तोः।
स्वस्थैः स्मृता मतिमतीव शुभां ददासि।।
दारिद्र्यदुःखभयहारिणि का त्वदन्या।
सर्वोपकारकरणाय सदार्द्रचित्ता।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः प्रदक्षिणनमस्कारान् समर्पयामि।।',
        'துர்கே ஸ்ம்ருதா ஹரஸி பீதிமஶேஷ-ஜந்தோ꞉।
ஸ்வஸ்தை꞉ ஸ்ம்ருதா மதிமதீவ ஶுபாம் ததாஸி।।
தாரித்ர்யது꞉கபயஹாரிணி கா த்வதந்யா।
ஸர்வோபகாரகரணாய ஸதார்த்ரசித்தா।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ ப்ரதக்ஷிணநமஸ்காராந் ஸமர்பயாமி।।',
        'durge smṛtā harasi bhītimaśeṣa-jantoḥ।
svasthaiḥ smṛtā matimatīva śubhāṃ dadāsi।।
dāridryaduḥkhabhayahāriṇi kā tvadanyā।
sarvopakārakaraṇāya sadārdracittā।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ pradakṣiṇanamaskārān samarpayāmi।।',
        'Durga, remembered, you take away the fear of every creature; remembered by those at ease, you give them a mind more blessed still. Remover of poverty, sorrow and fear, who but you has a heart always soft with the wish to help everyone?',
        'This verse is from the Devi Mahatmyam, the text recited through Navaratri. Smrta, "remembered", carries it: she does not need to be summoned with ceremony, only remembered, and the circling is a way of keeping her at the centre while doing it.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), p.300');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 26, 'uttara', '{main,punar}', 'Navadurga Pooja', 'நவதுர்கா பூஜை',
        'Offer a flower at each of the nine forms of Durga, from Shailaputri to Siddhidatri. On each day of Navaratri the form for that day may be honoured with an extra flower: Shailaputri on the first, Siddhidatri on the ninth.',
        'துர்கையின் ஒன்பது வடிவங்களுக்கும், ஶைலபுத்ரீ முதல் ஸித்திதாத்ரீ வரை, ஒவ்வொன்றிற்கும் ஒரு புஷ்பம் சமர்ப்பிக்கவும். நவராத்திரியின் ஒவ்வொரு நாளும் அந்நாளுக்கு உரிய வடிவத்திற்கு கூடுதலாக ஒரு புஷ்பம் சமர்ப்பிக்கலாம் — முதல் நாள் ஶைலபுத்ரீ, ஒன்பதாம் நாள் ஸித்திதாத்ரீ.',
        null,
        null,
        null,
        'Salutations to the nine Durgas: Shailaputri, daughter of the mountain; Brahmacharini, the ascetic; Chandraghanta, crowned with the crescent; Kushmanda, who laughed the universe into being; Skandamata, mother of Skanda; Katyayani; Kalaratri, the night of time; Mahagauri, the radiant; and Siddhidatri, giver of attainment.',
        'The nine forms run in a line from a girl, the mountain''s daughter, through the ascetic, the warrior and the mother, to the one who grants completion. Read in order they are a life, which is why there is one for each night.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), p.300; two-column list read in the canonical order of the nine forms');

insert into public.archana_items
  (pooja_step_id, seq, invoked_name_deva, invoked_name_ta, invoked_name_translit,
   offering_deva, offering_en, offering_ta)
values
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 26), 1, 'ॐ शैलपुत्र्यै नमः', 'ஓம் ஶைலபுத்ர்யை நம꞉', 'oṃ śailaputryai namaḥ', null, 'Offer a flower', 'புஷ்பம் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 26), 2, 'ॐ ब्रह्मचारिण्यै नमः', 'ஓம் ப்ரஹ்மசாரிண்யை நம꞉', 'oṃ brahmacāriṇyai namaḥ', null, 'Offer a flower', 'புஷ்பம் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 26), 3, 'ॐ चन्द्रघण्टायै नमः', 'ஓம் சந்த்ரகண்டாயை நம꞉', 'oṃ candraghaṇṭāyai namaḥ', null, 'Offer a flower', 'புஷ்பம் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 26), 4, 'ॐ कूष्माण्डायै नमः', 'ஓம் கூஷ்மாண்டாயை நம꞉', 'oṃ kūṣmāṇḍāyai namaḥ', null, 'Offer a flower', 'புஷ்பம் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 26), 5, 'ॐ स्कन्दमात्रे नमः', 'ஓம் ஸ்கந்தமாத்ரே நம꞉', 'oṃ skandamātre namaḥ', null, 'Offer a flower', 'புஷ்பம் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 26), 6, 'ॐ कात्यायिन्यै नमः', 'ஓம் காத்யாயிந்யை நம꞉', 'oṃ kātyāyinyai namaḥ', null, 'Offer a flower', 'புஷ்பம் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 26), 7, 'ॐ कालरात्र्यै नमः', 'ஓம் காலராத்ர்யை நம꞉', 'oṃ kālarātryai namaḥ', null, 'Offer a flower', 'புஷ்பம் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 26), 8, 'ॐ महागौर्यै नमः', 'ஓம் மஹாகௌர்யை நம꞉', 'oṃ mahāgauryai namaḥ', null, 'Offer a flower', 'புஷ்பம் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 26), 9, 'ॐ सिद्धिदायै नमः', 'ஓம் ஸித்திதாயை நம꞉', 'oṃ siddhidāyai namaḥ', null, 'Offer a flower', 'புஷ்பம் சமர்ப்பிக்கவும்');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 27, 'uttara', '{main,punar}', 'Jyoti Pooja', 'ஜ்யோதி பூஜை',
        'Offer flowers and akshatai to the lamp itself. The lamp lit on the first day is kept burning, or lit afresh at each pooja, through all nine days.',
        'தீபத்திற்கே புஷ்பமும் அக்ஷதையும் சமர்ப்பிக்கவும். முதல் நாள் ஏற்றிய தீபம் ஒன்பது நாட்களும் அணையாமல் வைக்கப்படுகிறது, அல்லது ஒவ்வொரு பூஜையிலும் புதிதாக ஏற்றப்படுகிறது.',
        'प्रधान साधार विकल्पसत्ता स्वभावभावात् भुवनत्रयस्य।
सा विद्यया व्यक्तमपीह माया ज्योतिः परा पातु जगन्ति नित्यम्।।
तेजस्स्वरूपायै श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः',
        'ப்ரதாந ஸாதார விகல்பஸத்தா ஸ்வபாவபாவாத் புவநத்ரயஸ்ய।
ஸா வித்யயா வ்யக்தமபீஹ மாயா ஜ்யோதி꞉ பரா பாது ஜகந்தி நித்யம்।।
தேஜஸ்ஸ்வரூபாயை ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉',
        'pradhāna sādhāra vikalpasattā svabhāvabhāvāt bhuvanatrayasya।
sā vidyayā vyaktamapīha māyā jyotiḥ parā pātu jaganti nityam।।
tejassvarūpāyai śrīdurgā lakṣmī sarasvatī devyai namaḥ',
        'She who, by her own nature, is the reality behind the three worlds, their ground and all their variety; the Maya made manifest here by knowledge: may that supreme light protect the worlds always. Salutations to Sri Durga, Lakshmi and Saraswati, whose form is radiance.',
        'Tejassvarupa, "whose form is radiance". The lamp is not a light shown to the Goddess here; it is worshipped as her. That is why it is kept burning through the nine nights rather than lit and put out with each pooja.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), pp.300-301');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 28, 'uttara', '{main,punar,udvasana}', 'Prarthana', 'ப்ரார்த்தனை',
        'With joined hands, pray to the Goddess.',
        'கைகூப்பி தேவியைப் ப்ரார்த்திக்கவும்.',
        'सर्वमङ्गल माङ्गल्ये शिवे सर्वार्थ साधिके।
शरण्ये त्र्यम्बके गौरि नारायणि नमोऽस्तु ते।।
रूपं देहि याशो देहि भगं भगवति देहि मे।
पुत्रान् देहि धनं देहि सर्वान् कामान् प्रदेहि मे।।',
        'ஸர்வமங்கல மாங்கல்யே ஶிவே ஸர்வார்த ஸாதிகே।
ஶரண்யே த்ர்யம்பகே கௌரி நாராயணி நமோஸ்து தே।।
ரூபம் தேஹி யாஶோ தேஹி பகம் பகவதி தேஹி மே।
புத்ராந் தேஹி தநம் தேஹி ஸர்வாந் காமாந் ப்ரதேஹி மே।।',
        'sarvamaṅgala māṅgalye śive sarvārtha sādhike।
śaraṇye tryambake gauri nārāyaṇi namo''stu te।।
rūpaṃ dehi yāśo dehi bhagaṃ bhagavati dehi me।
putrān dehi dhanaṃ dehi sarvān kāmān pradehi me।।',
        'Auspiciousness of all that is auspicious, Shiva, fulfiller of every aim, refuge, three-eyed Gauri, Narayani: salutations to you. Give me beauty, give me fame, give me good fortune, Goddess; give me children, give me wealth, give me all that I desire.',
        'Sarvamangala mangalye is the best known verse of the Devi Mahatmyam and the plainest. After nine days of upacharas it simply asks, out loud, for what a household wants. There is no embarrassment in the asking.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), p.301');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 29, 'uttara', '{main,punar}', 'Navakanya Pooja', 'நவகன்யா பூஜை',
        'Seat a girl under twelve, invoke the Goddess in her, and worship her with water for the feet and hands, a new cloth, sandal, turmeric and kumkumam, ornaments and flowers. Then offer a flower at each of the nine names. Usually one girl is honoured each day, or nine together on one day.',
        'பன்னிரண்டு வயதிற்குட்பட்ட ஒரு சிறுமியை அமர வைத்து, அவளிடம் தேவியை ஆவாஹனம் செய்து, பாத்யம், அர்க்யம், புது வஸ்திரம், சந்தனம், மஞ்சள் குங்குமம், ஆபரணம், புஷ்பம் சமர்ப்பித்துப் பூஜிக்கவும். பின் ஒன்பது நாமங்களுக்கும் ஒவ்வொரு புஷ்பம். பொதுவாக ஒவ்வொரு நாளும் ஒரு சிறுமி, அல்லது ஒரு நாளில் ஒன்பது பேர் சேர்ந்து.',
        'ॐ क्लीं कुलकुमारिकायै नमः
मन्त्राक्षरमयीं लक्ष्मीं मातृणांरूपधारिणीम्।
नवदुर्गात्मिकां साक्षात् कन्यामावाहयाम्यहम्।।
पाद्यं समर्पयामि
अर्घ्यं समर्पयामि
आचमनीयं समर्पयामि
वस्त्रम् समर्पयामि
गन्धम् समर्पयामि
हरिद्राकुङ्कुमं समर्पयामि
भूषणानि समर्पयामि
पुष्पाणि समर्पयामि',
        'ஓம் க்லீம் குலகுமாரிகாயை நம꞉
மந்த்ராக்ஷரமயீம் லக்ஷ்மீம் மாத்ருணாம்ரூபதாரிணீம்।
நவதுர்காத்மிகாம் ஸாக்ஷாத் கந்யாமாவாஹயாம்யஹம்।।
பாத்யம் ஸமர்பயாமி
அர்க்யம் ஸமர்பயாமி
ஆசமநீயம் ஸமர்பயாமி
வஸ்த்ரம் ஸமர்பயாமி
கந்தம் ஸமர்பயாமி
ஹரித்ராகுங்குமம் ஸமர்பயாமி
பூஷணாநி ஸமர்பயாமி
புஷ்பாணி ஸமர்பயாமி',
        'oṃ klīṃ kulakumārikāyai namaḥ
mantrākṣaramayīṃ lakṣmīṃ mātṛṇāṃrūpadhāriṇīm।
navadurgātmikāṃ sākṣāt kanyāmāvāhayāmyaham।।
pādyaṃ samarpayāmi
arghyaṃ samarpayāmi
ācamanīyaṃ samarpayāmi
vastram samarpayāmi
gandham samarpayāmi
haridrākuṅkumaṃ samarpayāmi
bhūṣaṇāni samarpayāmi
puṣpāṇi samarpayāmi',
        'Om klim, salutations to the maiden of the family. I invoke the maiden who is Lakshmi made of the letters of the mantra, who takes the form of the mothers, the nine Durgas in person. I offer water for the feet, water for the hands, water to sip, a cloth, sandal, turmeric and kumkumam, ornaments and flowers. Salutations to Kaumari, Tripura, Kalyani, Rohini, Kamini, Chandika, Shankari, Durga and Subhadra.',
        'Every other step of the pooja treats an image as the Goddess. This one treats a child as the Goddess, and gives her exactly the upacharas the kalasham received. It is the clearest statement in the whole festival of where the divine is supposed to be looked for.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), pp.301-302; the nine names read in the order of the maidens'' ages, Kumari to Subhadra');

insert into public.archana_items
  (pooja_step_id, seq, invoked_name_deva, invoked_name_ta, invoked_name_translit,
   offering_deva, offering_en, offering_ta)
values
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 29), 1, 'ॐ क्लीं कौमार्यै नमः', 'ஓம் க்லீம் கௌமார்யை நம꞉', 'oṃ klīṃ kaumāryai namaḥ', null, 'Offer a flower', 'புஷ்பம் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 29), 2, 'ॐ त्रिपुरायै नमः', 'ஓம் த்ரிபுராயை நம꞉', 'oṃ tripurāyai namaḥ', null, 'Offer a flower', 'புஷ்பம் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 29), 3, 'ॐ कल्याण्यै नमः', 'ஓம் கல்யாண்யை நம꞉', 'oṃ kalyāṇyai namaḥ', null, 'Offer a flower', 'புஷ்பம் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 29), 4, 'ॐ रोहिण्यै नमः', 'ஓம் ரோஹிண்யை நம꞉', 'oṃ rohiṇyai namaḥ', null, 'Offer a flower', 'புஷ்பம் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 29), 5, 'ॐ कामिन्यै नमः', 'ஓம் காமிந்யை நம꞉', 'oṃ kāminyai namaḥ', null, 'Offer a flower', 'புஷ்பம் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 29), 6, 'ॐ चण्डिकायै नमः', 'ஓம் சண்டிகாயை நம꞉', 'oṃ caṇḍikāyai namaḥ', null, 'Offer a flower', 'புஷ்பம் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 29), 7, 'ॐ शाङ्कर्यै नमः', 'ஓம் ஶாங்கர்யை நம꞉', 'oṃ śāṅkaryai namaḥ', null, 'Offer a flower', 'புஷ்பம் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 29), 8, 'ॐ दुर्गायै नमः', 'ஓம் துர்காயை நம꞉', 'oṃ durgāyai namaḥ', null, 'Offer a flower', 'புஷ்பம் சமர்ப்பிக்கவும்'),
  ((select id from public.pooja_steps where pooja_id = 'navaratri_pooja' and step_number = 29), 9, 'ॐ सुभद्रायै नमः', 'ஓம் ஸுபத்ராயை நம꞉', 'oṃ subhadrāyai namaḥ', null, 'Offer a flower', 'புஷ்பம் சமர்ப்பிக்கவும்');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 30, 'uttara', '{main,punar}', 'Kanya Neerajanam & Prarthana', 'கன்யா நீராஜனம் & ப்ரார்த்தனை',
        'Show incense and a lamp to the girl, offer her food, then wave camphor, and pray. Send her home with tambulam, a blouse piece or a small gift.',
        'சிறுமிக்கு தூபம், தீபம் காட்டி, உணவு அளித்து, கற்பூர ஆரத்தி செய்து, ப்ரார்த்திக்கவும். தாம்பூலம், ரவிக்கைத் துணி அல்லது சிறு பரிசு கொடுத்து அனுப்பவும்.',
        'धूपं आघ्रापयामि
दीपं दर्शयामि
नैवेद्यं निवेदयामि
निवेदनानन्तरं आचमनीयं समर्पयामि।
कर्पूर नीराजनम् समर्पयामि
नीराजनानन्तरं आचमनीयं समर्पयामि
रूपं देहि जयं देहि यशो देहि द्विषो जहि।
महिषघ्नि महामाये चामुण्डे मुण्डमालिनि।
आयुरारोग्यमैश्वर्यं देहि देवि नमोऽस्तु ते।। प्रार्थनां समर्पयामि',
        'தூபம் ஆக்ராபயாமி
தீபம் தர்ஶயாமி
நைவேத்யம் நிவேதயாமி
நிவேதநாநந்தரம் ஆசமநீயம் ஸமர்பயாமி।
கர்பூர நீராஜநம் ஸமர்பயாமி
நீராஜநாநந்தரம் ஆசமநீயம் ஸமர்பயாமி
ரூபம் தேஹி ஜயம் தேஹி யஶோ தேஹி த்விஷோ ஜஹி।
மஹிஷக்நி மஹாமாயே சாமுண்டே முண்டமாலிநி।
ஆயுராரோக்யமைஶ்வர்யம் தேஹி தேவி நமோஸ்து தே।। ப்ரார்தநாம் ஸமர்பயாமி',
        'dhūpaṃ āghrāpayāmi
dīpaṃ darśayāmi
naivedyaṃ nivedayāmi
nivedanānantaraṃ ācamanīyaṃ samarpayāmi।
karpūra nīrājanam samarpayāmi
nīrājanānantaraṃ ācamanīyaṃ samarpayāmi
rūpaṃ dehi jayaṃ dehi yaśo dehi dviṣo jahi।
mahiṣaghni mahāmāye cāmuṇḍe muṇḍamālini।
āyurārogyamaiśvaryaṃ dehi devi namo''stu te।। prārthanāṃ samarpayāmi',
        'I offer incense, I show the lamp, I offer food and water to rinse, I offer the camphor flame and water after it. Give me beauty, give me victory, give me fame, destroy my enemies, slayer of Mahisha, great Maya, Chamunda garlanded with skulls; give me long life, health and prosperity, Goddess: salutations to you. I offer my prayer.',
        'Rupam dehi jayam dehi yasho dehi dvisho jahi is the refrain of the Argala Stotram, said before the Devi Mahatmyam is read. It is said here to a child, which keeps the asking honest.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), p.303');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('navaratri_pooja', 31, 'uttara', '{udvasana}', 'Punah Pooja & Yathasthanam', 'புனர் பூஜை & யதாஸ்தானம்',
        'On Vijayadashami, after reciting the hundred and eight names and offering incense, lamp, fruit and milk and camphor, pray, prostrate, and move the kalasham or image a little towards the north. The Goddess is sent home with an invitation to come back next year.',
        'விஜயதசமியன்று, அஷ்டோத்தரம் சொல்லி, தூபம், தீபம், பழம், பால், கற்பூரம் சமர்ப்பித்த பின், ப்ரார்த்தித்து நமஸ்கரித்து, கலசத்தையோ விக்ரஹத்தையோ வடக்குப் பக்கம் சிறிது நகர்த்தவும். அடுத்த ஆண்டு மீண்டும் வர அழைத்து தேவிக்கு விடை கொடுக்கப்படுகிறது.',
        'उत्तिष्ठ देवि चण्डेशि शुभां पूजां प्रगृह्य।
कुरुष्व मे हि कल्याणं अष्टभिः शक्तिभिः सह।।
दुर्गेलक्ष्मी च वाग्देवि स्वस्थानं गच्छ पूजिते।
संवत्सरे व्यतीते तु पुनरागमनाय वै।।
इमां पूजां मया देवि यथाशक्ति उपपादिताम्।
रक्षार्थं त्वं समादाय व्रजस्व स्थानमुत्तमम् ।।
श्रीदुर्गां लक्ष्मीं सरस्वतीं यथास्थानं प्रतिष्ठापयामि।
शोभनार्थे क्षेमाय पुनरागमनाय च।।
नमस्कारान् समर्पयामि',
        'உத்திஷ்ட தேவி சண்டேஶி ஶுபாம் பூஜாம் ப்ரக்ருஹ்ய।
குருஷ்வ மே ஹி கல்யாணம் அஷ்டபி꞉ ஶக்திபி꞉ ஸஹ।।
துர்கேலக்ஷ்மீ ச வாக்தேவி ஸ்வஸ்தாநம் கச்ச பூஜிதே।
ஸம்வத்ஸரே வ்யதீதே து புநராகமநாய வை।।
இமாம் பூஜாம் மயா தேவி யதாஶக்தி உபபாதிதாம்।
ரக்ஷார்தம் த்வம் ஸமாதாய வ்ரஜஸ்வ ஸ்தாநமுத்தமம் ।।
ஶ்ரீதுர்காம் லக்ஷ்மீம் ஸரஸ்வதீம் யதாஸ்தாநம் ப்ரதிஷ்டாபயாமி।
ஶோபநார்தே க்ஷேமாய புநராகமநாய ச।।
நமஸ்காராந் ஸமர்பயாமி',
        'uttiṣṭha devi caṇḍeśi śubhāṃ pūjāṃ pragṛhya।
kuruṣva me hi kalyāṇaṃ aṣṭabhiḥ śaktibhiḥ saha।।
durgelakṣmī ca vāgdevi svasthānaṃ gaccha pūjite।
saṃvatsare vyatīte tu punarāgamanāya vai।।
imāṃ pūjāṃ mayā devi yathāśakti upapāditām।
rakṣārthaṃ tvaṃ samādāya vrajasva sthānamuttamam ।।
śrīdurgāṃ lakṣmīṃ sarasvatīṃ yathāsthānaṃ pratiṣṭhāpayāmi।
śobhanārthe kṣemāya punarāgamanāya ca।।
namaskārān samarpayāmi',
        'Rise, Goddess, Chandeshi, having received this auspicious worship, and do me good together with your eight powers. Durga, Lakshmi and Vagdevi, worshipped, go to your own place, to return again when the year has passed. Take this worship I have offered as I was able, Goddess, for my protection, and go to your highest place. I return Sri Durga, Lakshmi and Saraswati to their places, for what is good, for well-being, and for coming again. I offer my prostrations.',
        'Samvatsare vyatite tu punaragamanaya, "to return when the year has passed". The release is worded as a farewell between people who will see each other again, which is why Vijayadashami is a day for beginning things rather than an ending.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), p.304 punah pooja - yathaasthaanam');

