  ('navaratri_pooja', 2, 'Golu: a set of dolls on stepped shelves, if the house keeps a golu', 'கொலு படிகளும் பொம்மைகளும் (வழக்கம் இருந்தால்)', null, 'core', false, false, null),
  ('navaratri_pooja', 3, 'Pancha pathram and uddharani (water vessel and spoon)', 'பஞ்ச பாத்திரம் & உத்தரிணி', '1 set', 'vessel', false, false, null),
