  ('navaratri_pooja', 6, 'Kuthuvilakku (oil lamp) with ghee or oil and cotton wicks', 'குத்துவிளக்கு, நெய் அல்லது எண்ணெய், திரி', '1', 'vessel', false, false, null),
  ('navaratri_pooja', 7, 'Akshatai (rice with turmeric)', 'அக்ஷதை', null, 'offering', false, false, null),
  ('navaratri_pooja', 8, 'Manjal (turmeric) powder and kumkumam (vermilion)', 'மஞ்சள் தூள் & குங்குமம்', null, 'offering', false, false, null),
  ('navaratri_pooja', 9, 'Chandanam (sandalwood paste)', 'சந்தனம்', null, 'offering', false, false, null),
  ('navaratri_pooja', 10, 'Kanmai (kajal, black eye paste)', 'கண்மை', null, 'offering', false, false, null),
  ('navaratri_pooja', 11, 'New cloth or blouse piece for the Goddess', 'தேவிக்கு புது வஸ்திரம் அல்லது ரவிக்கைத் துணி', '1', 'offering', false, false, null),
  ('navaratri_pooja', 12, 'Udiri pushpam (loose flowers) and a garland', 'உதிரி புஷ்பம் & மாலை', null, 'flower', false, false, null),
  ('navaratri_pooja', 13, 'Agarbatti and karpooram (incense sticks and camphor)', 'ஊதுபத்தி & கற்பூரம்', null, 'offering', false, false, null),
  ('navaratri_pooja', 14, 'Vetrilai and paakku (betel leaves and areca nut)', 'வெற்றிலை & பாக்கு', null, 'offering', false, false, null),
  ('navaratri_pooja', 15, 'Fruits and banana', 'பழங்கள் & வாழைப்பழம்', null, 'offering', false, false, null),
  ('navaratri_pooja', 16, 'Tambulam for visiting sumangalis: betel, turmeric, kumkumam, a blouse piece, mirror, comb and bangles, one set each', 'சுமங்கலிகளுக்குத் தாம்பூலம்: வெற்றிலை, மஞ்சள், குங்குமம், ரவிக்கைத் துணி, கண்ணாடி, சீப்பு, வளையல்', 'one set per guest', 'offering', false, false, null);

