insert into public.naivedyam_items (pooja_id, tier, seq, name_en, name_ta, recipe_note, recipe_note_ta) values
  ('navaratri_pooja', 'primary', 1, 'Sundal', 'சுண்டல்', 'Boiled pulses tempered with mustard, curry leaves and grated coconut. A different pulse each day: chickpea, green gram, peanut, black-eyed pea and so on.', 'கடுகு, கறிவேப்பிலை, தேங்காய்த் துருவலுடன் தாளித்த வேகவைத்த பயறு. நாள்தோறும் வேறு பயறு: கொண்டைக்கடலை, பாசிப்பயறு, வேர்க்கடலை, காராமணி முதலியன.'),
  ('navaratri_pooja', 'primary', 2, 'Payasam', 'பாயசம்', 'Rice or vermicelli cooked in milk and sweetened.', 'பாலில் வேகவைத்து இனிப்பு சேர்த்த அரிசி அல்லது சேமியா.'),
  ('navaratri_pooja', 'secondary', 1, 'Annam', 'அன்னம்', 'Plain cooked rice, with the day''s meal.', null),
  ('navaratri_pooja', 'secondary', 2, 'Fruits with banana', 'பழங்கள் & வாழைப்பழம்', null, null),
  ('navaratri_pooja', 'secondary', 3, 'Milk', 'பால்', 'Offered with fruit on Vijayadashami.', 'விஜயதசமியன்று பழத்துடன் சமர்ப்பிக்கப்படுகிறது.');

