insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('saraswati_pooja', 9, 'pradhana', '{main}', 'Dhyanam', 'த்யானம்',
        'Arrange the books, a picture of Saraswati and any musical instruments on a clean cloth. With flowers and akshatai in hand, hold her form in mind, then offer them at the books, the picture or the instruments.',
        'புத்தகங்கள், ஸரஸ்வதியின் படம், இசைக் கருவிகள் இவற்றை சுத்தமான துணியின் மேல் வைக்கவும். கையில் புஷ்பமும் அக்ஷதையும் வைத்து அவள் வடிவத்தை மனதில் நிறுத்தி, புத்தகங்களிலோ படத்திலோ கருவிகளிலோ சமர்ப்பிக்கவும்.',
        'सरस्वतीं सत्यवासां सुधांशुसमविग्रहाम् ।
स्फटिकाक्षस्रजं पद्मं पुस्तकं च शुकं करैः।।
चतुर्भि-र्दधतीं देवीं चन्द्रबिंब समाननाम् ।
वल्लभामखिलार्थानां वल्लकीवादनप्रियाम् ।।
अस्मिन् पुस्तक मण्डले/ चित्रपटे/ वाद्यमण्डले
श्रीदुर्गा लक्ष्मी सरस्वतीं ध्यायामि',
        'ஸரஸ்வதீம் ஸத்யவாஸாம் ஸுதாம்ஶுஸமவிக்ரஹாம் ।
ஸ்படிகாக்ஷஸ்ரஜம் பத்மம் புஸ்தகம் ச ஶுகம் கரை꞉।।
சதுர்பி-ர்தததீம் தேவீம் சந்த்ரபிம்ப ஸமாநநாம் ।
வல்லபாமகிலார்தாநாம் வல்லகீவாதநப்ரியாம் ।।
அஸ்மிந் புஸ்தக மண்டலே/ சித்ரபடே/ வாத்யமண்டலே
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீம் த்யாயாமி',
        'sarasvatīṃ satyavāsāṃ sudhāṃśusamavigrahām ।
sphaṭikākṣasrajaṃ padmaṃ pustakaṃ ca śukaṃ karaiḥ।।
caturbhi-rdadhatīṃ devīṃ candrabiṃba samānanām ।
vallabhāmakhilārthānāṃ vallakīvādanapriyām ।।
asmin pustaka maṇḍale/ citrapaṭe/ vādyamaṇḍale
śrīdurgā lakṣmī sarasvatīṃ dhyāyāmi',
        'Saraswati, true in her garments, her body like the moon, holding in four hands a crystal rosary, a lotus, a book and a parrot; her face like the full moon, dear to all that has meaning, fond of playing the vina. In this circle of books, this picture, this circle of instruments, I meditate on Sri Durga, Lakshmi and Saraswati.',
        'Asmin pustaka mandale, chitrapate, vadyamandale: in the books, or the picture, or the instruments. The verse leaves the choice open because the Goddess of learning is worshipped in the tools of learning, whatever those are in a given house.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), p.307 dhyanam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('saraswati_pooja', 10, 'pradhana', '{main}', 'Avahanam', 'ஆவாஹனம்',
        'Invite the Goddess into the books, picture or instruments with folded hands, and offer flowers and akshatai.',
        'கைகூப்பி தேவியைப் புத்தகங்களிலோ படத்திலோ கருவிகளிலோ எழுந்தருளச் செய்து, புஷ்பம் அக்ஷதை சமர்ப்பிக்கவும்.',
        'भारतीं भावये देवीं भाषाणामधिदेवताम् ।
भावितां हृदये सद्भि-र्भामिनीं परमेष्ठिनः।।
चतुर्भुजां चन्द्रवर्णां चतुरानन-वल्लभाम् ।।
आवाहयामि वाणि त्वामाश्रितार्ति-विनाशिनीम् ।।
अस्मिन् पुस्तक मण्डले/ चित्रपटे/ वाद्यमण्डले
श्रीदुर्गा लक्ष्मी सरस्वतीं आवाहयामि।।',
        'பாரதீம் பாவயே தேவீம் பாஷாணாமதிதேவதாம் ।
பாவிதாம் ஹ்ருதயே ஸத்பி-ர்பாமிநீம் பரமேஷ்டிந꞉।।
சதுர்புஜாம் சந்த்ரவர்ணாம் சதுராநந-வல்லபாம் ।।
ஆவாஹயாமி வாணி த்வாமாஶ்ரிதார்தி-விநாஶிநீம் ।।
அஸ்மிந் புஸ்தக மண்டலே/ சித்ரபடே/ வாத்யமண்டலே
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீம் ஆவாஹயாமி।।',
        'bhāratīṃ bhāvaye devīṃ bhāṣāṇāmadhidevatām ।
bhāvitāṃ hṛdaye sadbhi-rbhāminīṃ parameṣṭhinaḥ।।
caturbhujāṃ candravarṇāṃ caturānana-vallabhām ।।
āvāhayāmi vāṇi tvāmāśritārti-vināśinīm ।।
asmin pustaka maṇḍale/ citrapaṭe/ vādyamaṇḍale
śrīdurgā lakṣmī sarasvatīṃ āvāhayāmi।।',
        'I hold in my heart Bharati, presiding goddess of all speech, held in the hearts of the good, consort of the Supreme Being; four-armed, moon-coloured, beloved of the four-faced Brahma. I invoke you, Vani, who destroy the distress of those who come to you. In this circle of books, picture or instruments, I invoke Sri Durga, Lakshmi and Saraswati.',
        'Bhashanam adhidevata, "presiding goddess of languages". She is invoked not over one sacred tongue but over speech itself, which makes a child''s school notebook as fit a seat for her as a palm-leaf manuscript.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), p.308 aavaahanam');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('saraswati_pooja', 11, 'pradhana', '{main}', 'Prana Pratishtha', 'ப்ராண ப்ரதிஷ்டை',
        'Touch the books or the picture with the fingertips of the right hand and ask the life breath to settle there. From now until Vijayadashami the books are not opened or read; they are the Goddess.',
        'வலது கை விரல் நுனிகளால் புத்தகங்களையோ படத்தையோ தொட்டு உயிர்ப்பு நிலைபெறும்படி வேண்டவும். இனி விஜயதசமி வரை புத்தகங்கள் திறக்கப்படுவதோ படிக்கப்படுவதோ இல்லை; அவை தேவியே.',
        'ॐ असुनीते पुनरस्मासु चक्षुः
पुनः प्राणमिह नो धेहि भोगम् ।
ज्योक्पश्येम सूर्यमुच्चरन्त
मनुमते मृडया नः स्वस्ति ।
अमृतं वै प्राणा अमृतमापः
प्राणानेव यथास्थानमुपह्वयते ॥
श्री सरस्वती देव्यै नमः ।
आवाहिता भव स्थापिता भव ।
सुप्रसन्ना भव वरदा भव ।
स्थिरासनं कुरु प्रसीद प्रसीद ।',
        'ஓம் அஸுநீதே புநரஸ்மாஸு சக்ஷு꞉
புந꞉ ப்ராணமிஹ நோ தேஹி போகம் ।
ஜ்யோக்பஶ்யேம ஸூர்யமுச்சரந்த
மநுமதே ம்ருடயா ந꞉ ஸ்வஸ்தி ।
அம்ருதம் வை ப்ராணா அம்ருதமாப꞉
ப்ராணாநேவ யதாஸ்தாநமுபஹ்வயதே ॥
ஶ்ரீ ஸரஸ்வதீ தேவ்யை நம꞉ ।
ஆவாஹிதா பவ ஸ்தாபிதா பவ ।
ஸுப்ரஸந்நா பவ வரதா பவ ।
ஸ்திராஸநம் குரு ப்ரஸீத ப்ரஸீத ।',
        'oṃ asunīte punarasmāsu cakṣuḥ
punaḥ prāṇamiha no dhehi bhogam ।
jyokpaśyema sūryamuccaranta
manumate mṛḍayā naḥ svasti ।
amṛtaṃ vai prāṇā amṛtamāpaḥ
prāṇāneva yathāsthānamupahvayate ॥
śrī sarasvatī devyai namaḥ ।
āvāhitā bhava sthāpitā bhava ।
suprasannā bhava varadā bhava ।
sthirāsanaṃ kuru prasīda prasīda ।',
        'Asuniti, restore to us our eyes, our breath and the joys of life, and let us look upon the rising sun for long; be gracious, Anumati, and bless us. The breaths are immortal, the waters are immortal; so the breaths are summoned each to its own place. Salutations to Sri Saraswati: be present, be established, be pleased, be bountiful, sit firm, be gracious.',
        'Once the books hold the Goddess they are not used, and that one day without study is the whole lesson: what is learnt is not a possession to be picked up at will, and on Vijayadashami it is received back as a gift.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), Prana pratishtha as the common section prescribes (step 18), feminine forms as carried for Varalakshmi');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('saraswati_pooja', 12, 'pradhana', '{main}', 'Asanam, Padyam, Arghyam & Achamaniyam', 'ஆஸனம், பாத்யம், அர்க்யம் & ஆசமனீயம்',
        'Offer flowers and akshatai as the seat, then water for the feet, water for the hands with akshatai, sandal and a flower, and scented water to sip, each poured from the uddharani into the plate.',
        'ஆஸனமாக புஷ்பம் அக்ஷதை சமர்ப்பித்து, பின் பாத்யம், அக்ஷதை சந்தனம் புஷ்பம் கலந்த அர்க்யம், வாசனை ஆசமனீயம் — ஒவ்வொன்றையும் உத்தரிணியால் தாம்பாளத்தில் விடவும்.',
        'आसनं संगृहाणेदमामिते सकलामरैः।
आहृते सर्वमुनिभिरार्तिदे सुरवैरिणाम् ।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः आसनं समर्पयामि
पाद्यमाद्यन्त शून्यायै वेद्यायै वेदवादिभिः
दास्यामि वाणि वरदे देवराजसमर्चिते।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः पाद्यं समर्पयामि
अघहन्त्रि गृहाणेदम् अर्घ्यमष्टांग संयुतम् ।
अंबाखिलानां जगताम् अंबुजासन सुन्दरि।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः अर्घ्यं समर्पयामि
आचम्यतां तोयमिदम् आश्रितार्थ-प्रदायिनि।
आत्मभू-वदनावासे आधिहारिणि ते नमः।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः आचमनीयं समर्पयामि',
        'ஆஸநம் ஸம்க்ருஹாணேதமாமிதே ஸகலாமரை꞉।
ஆஹ்ருதே ஸர்வமுநிபிரார்திதே ஸுரவைரிணாம் ।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ ஆஸநம் ஸமர்பயாமி
பாத்யமாத்யந்த ஶூந்யாயை வேத்யாயை வேதவாதிபி꞉
தாஸ்யாமி வாணி வரதே தேவராஜஸமர்சிதே।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ பாத்யம் ஸமர்பயாமி
அகஹந்த்ரி க்ருஹாணேதம் அர்க்யமஷ்டாம்க ஸம்யுதம் ।
அம்பாகிலாநாம் ஜகதாம் அம்புஜாஸந ஸுந்தரி।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ அர்க்யம் ஸமர்பயாமி
ஆசம்யதாம் தோயமிதம் ஆஶ்ரிதார்த-ப்ரதாயிநி।
ஆத்மபூ-வதநாவாஸே ஆதிஹாரிணி தே நம꞉।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ ஆசமநீயம் ஸமர்பயாமி',
        'āsanaṃ saṃgṛhāṇedamāmite sakalāmaraiḥ।
āhṛte sarvamunibhirārtide suravairiṇām ।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ āsanaṃ samarpayāmi
pādyamādyanta śūnyāyai vedyāyai vedavādibhiḥ
dāsyāmi vāṇi varade devarājasamarcite।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ pādyaṃ samarpayāmi
aghahantri gṛhāṇedam arghyamaṣṭāṃga saṃyutam ।
aṃbākhilānāṃ jagatām aṃbujāsana sundari।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ arghyaṃ samarpayāmi
ācamyatāṃ toyamidam āśritārtha-pradāyini।
ātmabhū-vadanāvāse ādhihāriṇi te namaḥ।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ ācamanīyaṃ samarpayāmi',
        'Accept this seat, brought by all the sages, you who are measureless to the gods and the scourge of their enemies. I give water for the feet, Vani, giver of boons, worshipped by Indra, to her who has neither beginning nor end and is known by those who speak the Veda. Destroyer of sin, lovely one on the lotus seat, mother of all the worlds: accept this arghyam of eight ingredients. Take this water to sip, you who grant what is sought, who dwell in the face of the self-born Brahma and take away distress: salutations.',
        'Adyanta shunya, "without beginning or end". The verse for washing her feet stops to say that she has no beginning; the courtesy of a host and the philosophy of the Veda sit in the same line.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), pp.309-310');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('saraswati_pooja', 13, 'pradhana', '{main}', 'Madhuparkam & Snanam', 'மதுபர்க்கம் & ஸ்நானம்',
        'Sprinkle three drops of milk, ghee, honey and curd mixed together, with a flower, as madhuparkam. Then offer panchamritam and clean water the same way, sprinkled rather than poured over the books, and a spoon of water to sip.',
        'பால், நெய், தேன், தயிர் கலந்த கலவையை புஷ்பத்தால் மூன்று துளி தெளித்து மதுபர்க்கம் சமர்ப்பிக்கவும். பின் பஞ்சாம்ருதமும் ஶுத்தோதகமும் அதே போல் — புத்தகங்களின் மேல் ஊற்றாமல் தெளித்து; பின் ஒரு ஸ்பூன் ஆசமனீயம்.',
        'मधुपर्कं गृहाणेदं मधुसूदन-वन्दिते।
मन्दस्मिते महादेवि महादेव-समर्चिते।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः मधुपर्कं समर्पयामि
पंचामृतं गृहाणेदं पंचानन-समर्चिते।
पयोदधिघृतोपेतं पंचपातकनाशिनि।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः पञ्चामृतस्नानं समर्पयामि
साध्वीनामग्रतो गण्ये साधुसङ्घसमादृते।
सरस्वति नमस्तुभ्यं स्नानं स्वीकुरु संप्रति।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः शुद्धोदकस्नानं समर्पयामि
स्नानानन्तरं आचमनीयं समर्पयामि।',
        'மதுபர்கம் க்ருஹாணேதம் மதுஸூதந-வந்திதே।
மந்தஸ்மிதே மஹாதேவி மஹாதேவ-ஸமர்சிதே।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ மதுபர்கம் ஸமர்பயாமி
பம்சாம்ருதம் க்ருஹாணேதம் பம்சாநந-ஸமர்சிதே।
பயோததிக்ருதோபேதம் பம்சபாதகநாஶிநி।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ பஞ்சாம்ருதஸ்நாநம் ஸமர்பயாமி
ஸாத்வீநாமக்ரதோ கண்யே ஸாதுஸங்கஸமாத்ருதே।
ஸரஸ்வதி நமஸ்துப்யம் ஸ்நாநம் ஸ்வீகுரு ஸம்ப்ரதி।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ ஶுத்தோதகஸ்நாநம் ஸமர்பயாமி
ஸ்நாநாநந்தரம் ஆசமநீயம் ஸமர்பயாமி।',
        'madhuparkaṃ gṛhāṇedaṃ madhusūdana-vandite।
mandasmite mahādevi mahādeva-samarcite।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ madhuparkaṃ samarpayāmi
paṃcāmṛtaṃ gṛhāṇedaṃ paṃcānana-samarcite।
payodadhighṛtopetaṃ paṃcapātakanāśini।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ pañcāmṛtasnānaṃ samarpayāmi
sādhvīnāmagrato gaṇye sādhusaṅghasamādṛte।
sarasvati namastubhyaṃ snānaṃ svīkuru saṃprati।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ śuddhodakasnānaṃ samarpayāmi
snānānantaraṃ ācamanīyaṃ samarpayāmi।',
        'Accept this madhuparkam, you who are praised by Madhusudana, gently smiling great Goddess worshipped by Mahadeva. Accept this panchamritam of milk, curd and ghee, you who are worshipped by the five-faced Shiva and destroy the five great sins. Counted first among the virtuous, honoured by the assembly of the good: salutations to you, Saraswati; take your bath now. After the bath I offer water to sip.',
        'Madhuparkam is honey and curd given to an honoured guest, a teacher or a bridegroom. Offering it to the books treats them as both at once.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), pp.310-311');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('saraswati_pooja', 14, 'pradhana', '{main}', 'Vastram & Upaveetam', 'வஸ்த்ரம் & உபவீதம்',
        'Drape a new cloth over the books or offer a pair of cloths, then the sacred thread or akshatai in its place.',
        'புத்தகங்களின் மேல் புதுத் துணி போர்த்தவும் அல்லது இரண்டு வஸ்திரங்களைச் சமர்ப்பிக்கவும்; பின் உபவீதம் அல்லது அதற்குப் பதில் அக்ஷதை.',
        'दुकूलद्वितयं देवि दुरितापह-वैभवे।
विधिप्रिये गृहाणेदं सुधानिधिसमं शिवे।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः वस्त्रयुग्मं समर्पयामि
उपवीतं गृहाणेदम् उपमाशून्यवैभवे।
हिरण्यगर्भमहिषि हिरण्यगुणैः कृतम् ।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः उपवीतं समर्पयामि',
        'துகூலத்விதயம் தேவி துரிதாபஹ-வைபவே।
விதிப்ரியே க்ருஹாணேதம் ஸுதாநிதிஸமம் ஶிவே।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ வஸ்த்ரயுக்மம் ஸமர்பயாமி
உபவீதம் க்ருஹாணேதம் உபமாஶூந்யவைபவே।
ஹிரண்யகர்பமஹிஷி ஹிரண்யகுணை꞉ க்ருதம் ।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ உபவீதம் ஸமர்பயாமி',
        'dukūladvitayaṃ devi duritāpaha-vaibhave।
vidhipriye gṛhāṇedaṃ sudhānidhisamaṃ śive।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ vastrayugmaṃ samarpayāmi
upavītaṃ gṛhāṇedam upamāśūnyavaibhave।
hiraṇyagarbhamahiṣi hiraṇyaguṇaiḥ kṛtam ।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ upavītaṃ samarpayāmi',
        'Accept this pair of fine cloths, Goddess whose splendour removes sin, dear to Brahma, auspicious one, like the ocean of nectar. Accept this sacred thread made of golden strands, queen of Hiranyagarbha, whose glory has no equal.',
        'Covering the books with a new cloth is how many houses close them for the day. The upachara and the household habit are the same act.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), p.311');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('saraswati_pooja', 15, 'pradhana', '{main}', 'Gandham, Mangala Dravyam & Abharanam', 'கந்தம், மங்கள த்ரவ்யம் & ஆபரணம்',
        'Apply sandal paste to the books, then a dot of turmeric and kumkumam and a touch of kajal, then offer ornaments.',
        'புத்தகங்களுக்கு சந்தனம் இட்டு, பின் மஞ்சள், குங்குமம், சிறிது கண்மை, பின் ஆபரணங்கள் சமர்ப்பிக்கவும்.',
        'अन्धकारिप्रियाराध्ये गन्धमुत्तमसौरभम् ।
गृहाण वाणि वरदे गन्धर्वपरिपूजिते।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः गन्धान् धारयामि
कुंकुमाञ्जन सिन्दूर कञ्चुकादिकमम्बिके।।
सौभाग्यद्रव्यमखिलं सुरवन्द्ये गृहाण मे।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः सौभाग्यद्रव्याणि समर्पयामि
वर्णरूपे गृहाणेदं स्वर्णवर्गपरिष्कृतम् ।
अर्णवोद्धृतरत्नाढ्यं कर्णभूषादिभूषणम् ।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः आभरणानि समर्पयामि',
        'அந்தகாரிப்ரியாராத்யே கந்தமுத்தமஸௌரபம் ।
க்ருஹாண வாணி வரதே கந்தர்வபரிபூஜிதே।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ கந்தாந் தாரயாமி
கும்குமாஞ்ஜந ஸிந்தூர கஞ்சுகாதிகமம்பிகே।।
ஸௌபாக்யத்ரவ்யமகிலம் ஸுரவந்த்யே க்ருஹாண மே।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ ஸௌபாக்யத்ரவ்யாணி ஸமர்பயாமி
வர்ணரூபே க்ருஹாணேதம் ஸ்வர்ணவர்கபரிஷ்க்ருதம் ।
அர்ணவோத்த்ருதரத்நாட்யம் கர்ணபூஷாதிபூஷணம் ।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ ஆபரணாநி ஸமர்பயாமி',
        'andhakāripriyārādhye gandhamuttamasaurabham ।
gṛhāṇa vāṇi varade gandharvaparipūjite।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ gandhān dhārayāmi
kuṃkumāñjana sindūra kañcukādikamambike।।
saubhāgyadravyamakhilaṃ suravandye gṛhāṇa me।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ saubhāgyadravyāṇi samarpayāmi
varṇarūpe gṛhāṇedaṃ svarṇavargapariṣkṛtam ।
arṇavoddhṛtaratnāḍhyaṃ karṇabhūṣādibhūṣaṇam ।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ ābharaṇāni samarpayāmi',
        'Accept this sandal of the finest fragrance, Vani, giver of boons, worshipped by the gandharvas, adored by the enemy of Andhaka. Kumkumam, kajal, sindoor, a bodice and all the auspicious things: accept them from me, Ambika, praised by the gods. Accept these ornaments for the ears and the rest, worked in gold and rich with gems from the ocean, you whose form is the letters.',
        'Varnarupe, "whose form is the letters". She is decorated as a goddess and addressed as the alphabet in the same verse, which is the most direct statement in the pooja of what is actually lying on the cloth.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), pp.311-312');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('saraswati_pooja', 16, 'pradhana', '{main}', 'Akshatai & Pushpam', 'அக்ஷதை & புஷ்பம்',
        'Offer akshatai, then a garland and loose flowers. White flowers are preferred for Saraswati.',
        'அக்ஷதை சமர்ப்பித்து, பின் மாலையும் உதிரிப் புஷ்பமும். ஸரஸ்வதிக்கு வெண்மையான புஷ்பங்கள் சிறப்பு.',
        'अक्षतांस्त्वं गृहाणेमानहतान् अमरार्चिते।
अक्षतेऽद्भुतरूपाढ्ये यक्षराजादिवन्दिते।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः अक्षतान् समर्पयामि
पुन्नाग-जातीमल्ल्यादि पुष्पजातं गृहाण मे।
पुमर्थदायिनि परे पुस्तकाढ्य-करांबुजे।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः
पुष्पमालां समर्पयामि। पुष्पैः पूजयामि।',
        'அக்ஷதாம்ஸ்த்வம் க்ருஹாணேமாநஹதாந் அமரார்சிதே।
அக்ஷதேத்புதரூபாட்யே யக்ஷராஜாதிவந்திதே।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ அக்ஷதாந் ஸமர்பயாமி
புந்நாக-ஜாதீமல்ல்யாதி புஷ்பஜாதம் க்ருஹாண மே।
புமர்ததாயிநி பரே புஸ்தகாட்ய-கராம்புஜே।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉
புஷ்பமாலாம் ஸமர்பயாமி। புஷ்பை꞉ பூஜயாமி।',
        'akṣatāṃstvaṃ gṛhāṇemānahatān amarārcite।
akṣate''dbhutarūpāḍhye yakṣarājādivandite।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ akṣatān samarpayāmi
punnāga-jātīmallyādi puṣpajātaṃ gṛhāṇa me।
pumarthadāyini pare pustakāḍhya-karāṃbuje।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ
puṣpamālāṃ samarpayāmi। puṣpaiḥ pūjayāmi।',
        'Accept these unbroken grains, you who are worshipped by the immortals, imperishable one rich in wondrous form, honoured by the king of the yakshas. Accept these punnaga, jasmine and other flowers, supreme one who grants the aims of life, whose lotus hand holds a book.',
        'Akshate, "imperishable one", over akshata, the unbroken grain. The pun is the point: learning is the one wealth that is not used up by being given away.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), pp.312-313');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('saraswati_pooja', 17, 'pradhana', '{main}', 'Anga Pooja', 'அங்க பூஜை',
        'Twenty names, each with a limb, from the feet up to the head and then the whole body. Offer a flower or a pinch of akshatai at each.',
        'இருபது நாமங்கள், ஒவ்வொன்றும் ஒரு அங்கத்துடன், பாதம் முதல் சிரசு வரை, கடைசியில் முழு உடல். ஒவ்வொன்றிலும் புஷ்பமோ சிறிது அக்ஷதையோ சமர்ப்பிக்கவும்.',
        null,
        null,
        null,
        'Twenty names of Saraswati, each offered to a limb from the feet upward: Pavana at the feet, Jalajasana at the knees, Vagdevi at the face, Kala at the forehead, and Mahasaraswati for the whole body.',
        'Every name in this list belongs to Saraswati alone, unlike the upachara lines, which address all three goddesses. Here, touching the image limb by limb, the worship narrows to her.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), pp.313-314');

insert into public.archana_items
  (pooja_step_id, seq, invoked_name_deva, invoked_name_ta, invoked_name_translit,
   offering_deva, offering_en, offering_ta)
values
  ((select id from public.pooja_steps where pooja_id = 'saraswati_pooja' and step_number = 17), 1, 'ॐ पावनायै नमः', 'ஓம் பாவநாயை நம꞉', 'oṃ pāvanāyai namaḥ', 'पादौ पूजयामि', 'Worship the feet', 'பாதௌ பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'saraswati_pooja' and step_number = 17), 2, 'ॐ गिरे नमः', 'ஓம் கிரே நம꞉', 'oṃ gire namaḥ', 'गुल्फौ पूजयामि', 'Worship the ankle', 'குல்பௌ பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'saraswati_pooja' and step_number = 17), 3, 'ॐ जगद्वन्द्यायै नमः', 'ஓம் ஜகத்வந்த்யாயை நம꞉', 'oṃ jagadvandyāyai namaḥ', 'जङ्घे पूजयामि', 'Worship the shanks', 'ஜங்கே பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'saraswati_pooja' and step_number = 17), 4, 'ॐ जलजासनायै नमः', 'ஓம் ஜலஜாஸநாயை நம꞉', 'oṃ jalajāsanāyai namaḥ', 'जानुनी पूजयामि', 'Worship the knee', 'ஜாநுநீ பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'saraswati_pooja' and step_number = 17), 5, 'ॐ उत्तमायै नमः', 'ஓம் உத்தமாயை நம꞉', 'oṃ uttamāyai namaḥ', 'ऊरू पूजयामि', 'Worship the thigh', 'ஊரூ பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'saraswati_pooja' and step_number = 17), 6, 'ॐ कमलासनप्रियायै नमः', 'ஓம் கமலாஸநப்ரியாயை நம꞉', 'oṃ kamalāsanapriyāyai namaḥ', 'कटिं पूजयामि', 'Worship the waist', 'கடிம் பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'saraswati_pooja' and step_number = 17), 7, 'ॐ नानाविद्यायै नमः', 'ஓம் நாநாவித்யாயை நம꞉', 'oṃ nānāvidyāyai namaḥ', 'नाभिं पूजयामि', 'Worship the navel', 'நாபிம் பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'saraswati_pooja' and step_number = 17), 8, 'ॐ वाण्यै नमः', 'ஓம் வாண்யை நம꞉', 'oṃ vāṇyai namaḥ', 'वक्षः पूजयामि', 'Worship the chest', 'வக்ஷ꞉ பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'saraswati_pooja' and step_number = 17), 9, 'ॐ उमायै नमः', 'ஓம் உமாயை நம꞉', 'oṃ umāyai namaḥ', 'हस्तौ पूजयामि', 'Worship the hands', 'ஹஸ்தௌ பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'saraswati_pooja' and step_number = 17), 10, 'ॐ रमायै नमः', 'ஓம் ரமாயை நம꞉', 'oṃ ramāyai namaḥ', 'स्कन्धौ पूजयामि', 'Worship the shoulders', 'ஸ்கந்தௌ பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'saraswati_pooja' and step_number = 17), 11, 'ॐ कलारूपिण्यै नमः', 'ஓம் கலாரூபிண்யை நம꞉', 'oṃ kalārūpiṇyai namaḥ', 'कण्ठं पूजयामि', 'Worship the neck', 'கண்டம் பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'saraswati_pooja' and step_number = 17), 12, 'ॐ भाषायै नमः', 'ஓம் பாஷாயை நம꞉', 'oṃ bhāṣāyai namaḥ', 'बाहून् पूजयामि', 'Worship the arms', 'பாஹூந் பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'saraswati_pooja' and step_number = 17), 13, 'ॐ चिरन्तनायै नमः', 'ஓம் சிரந்தநாயை நம꞉', 'oṃ cirantanāyai namaḥ', 'चुबुकं पूजयामि', 'Worship the chin', 'சுபுகம் பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'saraswati_pooja' and step_number = 17), 14, 'ॐ मुग्धस्मितायै नमः', 'ஓம் முக்தஸ்மிதாயை நம꞉', 'oṃ mugdhasmitāyai namaḥ', 'मुखं पूजयामि', 'Worship the face', 'முகம் பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'saraswati_pooja' and step_number = 17), 15, 'ॐ लोलेक्षणायै नमः', 'ஓம் லோலேக்ஷணாயை நம꞉', 'oṃ lolekṣaṇāyai namaḥ', 'नेत्रे पूजयामि', 'Worship the eyes', 'நேத்ரே பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'saraswati_pooja' and step_number = 17), 16, 'ॐ कलायै नमः', 'ஓம் கலாயை நம꞉', 'oṃ kalāyai namaḥ', 'ललाटं पूजयामि', 'Worship the forehead', 'லலாடம் பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'saraswati_pooja' and step_number = 17), 17, 'ॐ वर्णरूपायै नमः', 'ஓம் வர்ணரூபாயை நம꞉', 'oṃ varṇarūpāyai namaḥ', 'कर्णौ पूजयामि', 'Worship the ears', 'கர்ணௌ பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'saraswati_pooja' and step_number = 17), 18, 'ॐ अक्षररूपिण्यै नमः', 'ஓம் அக்ஷரரூபிண்யை நம꞉', 'oṃ akṣararūpiṇyai namaḥ', 'अलकान् पूजयामि', 'Worship the hair lock', 'அலகாந் பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'saraswati_pooja' and step_number = 17), 19, 'ॐ शिवायै नमः', 'ஓம் ஶிவாயை நம꞉', 'oṃ śivāyai namaḥ', 'शिरः पूजयामि', 'Worship the head', 'ஶிர꞉ பூஜயாமி'),
  ((select id from public.pooja_steps where pooja_id = 'saraswati_pooja' and step_number = 17), 20, 'ॐ श्री महासरस्वत्यै नमः', 'ஓம் ஶ்ரீ மஹாஸரஸ்வத்யை நம꞉', 'oṃ śrī mahāsarasvatyai namaḥ', 'सर्वाण्यंगानि पूजयामि', 'Worship the whole body', 'ஸர்வாண்யம்காநி பூஜயாமி');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('saraswati_pooja', 18, 'pradhana', '{main,udvasana}', 'Saraswati Ashtottara Shatanamavali', 'ஸரஸ்வதீ அஷ்டோத்தர ஶதநாமாவளி',
        'Offer a flower or a pinch of akshatai at each of the hundred and eight names. On Vijayadashami the names are said again before the books are taken up.',
        'நூற்றெட்டு நாமங்களில் ஒவ்வொன்றிலும் புஷ்பமோ சிறிது அக்ஷதையோ சமர்ப்பிக்கவும். விஜயதசமியன்று புத்தகங்களை எடுப்பதற்கு முன் இந்த நாமங்கள் மீண்டும் சொல்லப்படுகின்றன.',
        null,
        null,
        null,
        'One hundred and eight names of Saraswati, from Saraswati, Mahabhadra and Mahamaya to Brahmavishnushivatmika. Three names, Mahabhadra, Vaishnavi and Vagdevi, occur twice in the list, as is usual for this ashtottaram.',
        'Many of the names are warrior names, Chandika and the slayer of Dhumralochana, alongside the names of speech and learning. Saraswati is not only the gentle figure with the vina; understanding is also what defeats what is false.', 'all', true, false,
        'saraswati_ashtottara_108', 'Sampradaya Vratha Pooja Vidhi (Giri), pp.315-318, count markers verified in both scripts');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('saraswati_pooja', 19, 'uttara', '{main,udvasana}', 'Dhoopam & Deepam', 'தூபம் & தீபம்',
        'Wave incense before the books and the picture, then the ghee lamp, ringing the bell, and offer a spoon of water.',
        'புத்தகங்களுக்கும் படத்திற்கும் ஊதுபத்தி காட்டி, பின் நெய் தீபம் காட்டவும், மணி அடித்தபடி; பின் ஒரு ஸ்பூன் ஜலம்.',
        'धूपं गृहाण देवेशि धूम्रलोचन मर्दिनि।
गुग्गुल्वगरु संयुक्तं भक्त्या दत्तं विधिप्रिये।।
श्रीदुर्गा लक्ष्मी सरस्वतीदेव्यै नमः धूपं आघ्रापयामि
कृताग्नवर्ति तृतयैर्दीपितं दीपमंबिके
गृहाण वाणि वरदे कमलासन वल्लभे।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः दीपं दर्शयामि
धूप,दीपानन्तरं आचमनीयं समर्पयामि',
        'தூபம் க்ருஹாண தேவேஶி தூம்ரலோசந மர்திநி।
குக்குல்வகரு ஸம்யுக்தம் பக்த்யா தத்தம் விதிப்ரியே।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீதேவ்யை நம꞉ தூபம் ஆக்ராபயாமி
க்ருதாக்நவர்தி த்ருதயைர்தீபிதம் தீபமம்பிகே
க்ருஹாண வாணி வரதே கமலாஸந வல்லபே।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ தீபம் தர்ஶயாமி
தூப,தீபாநந்தரம் ஆசமநீயம் ஸமர்பயாமி',
        'dhūpaṃ gṛhāṇa deveśi dhūmralocana mardini।
guggulvagaru saṃyuktaṃ bhaktyā dattaṃ vidhipriye।।
śrīdurgā lakṣmī sarasvatīdevyai namaḥ dhūpaṃ āghrāpayāmi
kṛtāgnavarti tṛtayairdīpitaṃ dīpamaṃbike
gṛhāṇa vāṇi varade kamalāsana vallabhe।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ dīpaṃ darśayāmi
dhūpa,dīpānantaraṃ ācamanīyaṃ samarpayāmi',
        'Accept this incense with guggulu and aloe, offered with devotion, Queen of the gods, slayer of Dhumralochana, dear to Brahma. Accept the lamp lit with three wicks, Ambika, Vani, giver of boons, beloved of the lotus-seated one. After incense and lamp, I offer water to sip.',
        'Dhumralochana is the demon whose name means "smoke-eyed". He is slain in the verse offering incense smoke, which is the kind of joke these verses like to make.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), p.319');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('saraswati_pooja', 20, 'uttara', '{main,udvasana}', 'Naivedyam & Tambulam', 'நைவேத்யம் & தாம்பூலம்',
        'Set the food on a plate or plantain leaf on a cleaned spot. Sprinkle it with the vyahritis, say the Gayatri, circle water around it, offer water beneath it, and gesture as if feeding at each svaha. Name the dishes, offer water between and after, then betel and areca nut. In the evening the sprinkling line is said the other way round: ritam tva satyena parishinchami.',
        'சுத்தம் செய்த இடத்தில் தட்டிலோ வாழையிலையிலோ நைவேத்யத்தை வைக்கவும். வ்யாஹ்ருதிகளுடன் தெளித்து, காயத்ரீ சொல்லி, ஜலத்தால் சுற்றி, அடியில் ஜலம் விட்டு, ஒவ்வொரு ஸ்வாஹாவிற்கும் ஊட்டுவது போல் கை காட்டவும். உணவுகளைச் சொல்லி, நடுவிலும் முடிவிலும் ஜலம், பின் வெற்றிலை பாக்கு. மாலையில் தெளிக்கும் வரி மாற்றிச் சொல்லப்படும்: ருதம் த்வா ஸத்யேன பரிஷிஞ்சாமி.',
        'ॐ भूर्भुवस्सुवः
तत्सवितुर्वरेण्यं भर्गोदेवस्य धीमहि, धियो यो नः प्रचोदयात्
देवसवितः प्रसुव। सत्यं त्वर्तेन परिषिञ्चामि।
अमृतोपस्तरणमसि ।
ॐ प्राणाय स्वाहा, ॐ अपानाय स्वाहा, ॐ व्यानाय स्वाहा,
ॐ उदानाय स्वाहा, ॐ समानाय स्वाहा, ॐ ब्रह्मणे स्वाहा।
नैवेद्यं षड्रसोपेतं नानाभक्ष्य समन्वितम्।
पायसान्नं च संप्रीत्या ददामि प्रतिगृह्यताम् ।।
श्रीदुर्गा लक्ष्मी सरस्वतीदेव्यै नमः शाल्यान्नं, घृतगुल पायसं, माषापूपं,
गुडापूपं, लड्डुकं, नारिकेलखण्डद्वयं, कदलीफलं महानैवेद्यं
निवेदयामि।
मध्ये मध्ये अमृतपानीयं समर्पयामि ।
अमृतापिधानमसि। उत्तरापोशनं समर्पयामि।
निवेदनानन्तरं आचमनीयं समर्पयामि
पूगीफल समायुक्तं नागवल्ली दलैर्युतम्।
कर्पूरचूर्ण संयुक्तं तांबूलं प्रतिगृह्यताम् ।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः कर्पूरताम्बूलं समर्पयामि।।',
        'ஓம் பூர்புவஸ்ஸுவ꞉
தத்ஸவிதுர்வரேண்யம் பர்கோதேவஸ்ய தீமஹி, தியோ யோ ந꞉ ப்ரசோதயாத்
தேவஸவித꞉ ப்ரஸுவ। ஸத்யம் த்வர்தேந பரிஷிஞ்சாமி।
அம்ருதோபஸ்தரணமஸி ।
ஓம் ப்ராணாய ஸ்வாஹா, ஓம் அபாநாய ஸ்வாஹா, ஓம் வ்யாநாய ஸ்வாஹா,
ஓம் உதாநாய ஸ்வாஹா, ஓம் ஸமாநாய ஸ்வாஹா, ஓம் ப்ரஹ்மணே ஸ்வாஹா।
நைவேத்யம் ஷட்ரஸோபேதம் நாநாபக்ஷ்ய ஸமந்விதம்।
பாயஸாந்நம் ச ஸம்ப்ரீத்யா ததாமி ப்ரதிக்ருஹ்யதாம் ।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீதேவ்யை நம꞉ ஶால்யாந்நம், க்ருதகுல பாயஸம், மாஷாபூபம்,
குடாபூபம், லட்டுகம், நாரிகேலகண்டத்வயம், கதலீபலம் மஹாநைவேத்யம்
நிவேதயாமி।
மத்யே மத்யே அம்ருதபாநீயம் ஸமர்பயாமி ।
அம்ருதாபிதாநமஸி। உத்தராபோஶநம் ஸமர்பயாமி।
நிவேதநாநந்தரம் ஆசமநீயம் ஸமர்பயாமி
பூகீபல ஸமாயுக்தம் நாகவல்லீ தலைர்யுதம்।
கர்பூரசூர்ண ஸம்யுக்தம் தாம்பூலம் ப்ரதிக்ருஹ்யதாம் ।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ கர்பூரதாம்பூலம் ஸமர்பயாமி।।',
        'oṃ bhūrbhuvassuvaḥ
tatsaviturvareṇyaṃ bhargodevasya dhīmahi, dhiyo yo naḥ pracodayāt
devasavitaḥ prasuva। satyaṃ tvartena pariṣiñcāmi।
amṛtopastaraṇamasi ।
oṃ prāṇāya svāhā, oṃ apānāya svāhā, oṃ vyānāya svāhā,
oṃ udānāya svāhā, oṃ samānāya svāhā, oṃ brahmaṇe svāhā।
naivedyaṃ ṣaḍrasopetaṃ nānābhakṣya samanvitam।
pāyasānnaṃ ca saṃprītyā dadāmi pratigṛhyatām ।।
śrīdurgā lakṣmī sarasvatīdevyai namaḥ śālyānnaṃ, ghṛtagula pāyasaṃ, māṣāpūpaṃ,
guḍāpūpaṃ, laḍḍukaṃ, nārikelakhaṇḍadvayaṃ, kadalīphalaṃ mahānaivedyaṃ
nivedayāmi।
madhye madhye amṛtapānīyaṃ samarpayāmi ।
amṛtāpidhānamasi। uttarāpośanaṃ samarpayāmi।
nivedanānantaraṃ ācamanīyaṃ samarpayāmi
pūgīphala samāyuktaṃ nāgavallī dalairyutam।
karpūracūrṇa saṃyuktaṃ tāṃbūlaṃ pratigṛhyatām ।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ karpūratāmbūlaṃ samarpayāmi।।',
        'Om bhur bhuvah suvah; we meditate on the radiance of Savitr; may it inspire our minds. I sprinkle you with truth and order. To the five breaths and to Brahman, hail. Food of the six tastes with many dishes, and rice cooked in milk, I give with love: accept it. I offer cooked rice, payasam with ghee and jaggery, urad and jaggery cakes, laddu, two halves of a coconut and banana as the great offering. Water between and water to close. Betel leaves with areca nut and powdered camphor: accept this tambulam.',
        'The menu is named in the mantra itself: rice, payasam, two kinds of appam, laddu, coconut and banana. It is a festival meal, and the Goddess is fed it before anyone else in the house.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), pp.319-321');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('saraswati_pooja', 21, 'uttara', '{main,udvasana}', 'Karpura Neerajanam', 'கற்பூர நீராஜனம்',
        'Light camphor and wave it three times clockwise before the books and the picture, ringing the bell, then offer a spoon of water.',
        'கற்பூரம் ஏற்றி புத்தகங்களுக்கும் படத்திற்கும் மூன்று முறை வலமாகச் சுற்றிக் காட்டவும், மணி அடித்தபடி; பின் ஒரு ஸ்பூன் ஜலம்.',
        'कृतवर्ति सहस्रैश्च कर्पूर शकलैस्तदा।
नीराजनं मया दत्तं गृहाण वरदा भव ।।
श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः कर्पूरनीराजनं दर्शयामि।।
नीराजनानन्तरं आचमनीयं समर्पयामि',
        'க்ருதவர்தி ஸஹஸ்ரைஶ்ச கர்பூர ஶகலைஸ்ததா।
நீராஜநம் மயா தத்தம் க்ருஹாண வரதா பவ ।।
ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ கர்பூரநீராஜநம் தர்ஶயாமி।।
நீராஜநாநந்தரம் ஆசமநீயம் ஸமர்பயாமி',
        'kṛtavarti sahasraiśca karpūra śakalaistadā।
nīrājanaṃ mayā dattaṃ gṛhāṇa varadā bhava ।।
śrīdurgā lakṣmī sarasvatī devyai namaḥ karpūranīrājanaṃ darśayāmi।।
nīrājanānantaraṃ ācamanīyaṃ samarpayāmi',
        'With a thousand wicks and pieces of camphor I offer you this waving of light: accept it and grant boons. After the neerajanam I offer water to sip.',
        'Camphor burns away entirely and leaves nothing behind. Waved before the books, it is a picture of the hope that what is learnt is taken in completely.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), pp.321-322');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('saraswati_pooja', 22, 'uttara', '{main}', 'Mantra Pushpam & Pradakshina', 'மந்த்ர புஷ்பம் & ப்ரதக்ஷிணம்',
        'Offer flowers and akshatai with both hands; everyone present may offer. Then go round clockwise with palms joined, or turn in place.',
        'இரு கைகளாலும் புஷ்பமும் அக்ஷதையும் சமர்ப்பிக்கவும்; அனைவரும் சமர்ப்பிக்கலாம். பின் கைகூப்பி வலமாகச் சுற்றவும், அல்லது நின்ற இடத்தில் சுற்றவும்.',
        'श्रीदुर्गा लक्ष्मी सरस्वती देव्यै नमः मन्त्रपुष्पं समर्पयामि।।
यानि कानि च पापानि जन्मान्तर कृतानि च ।
तानि तानि विनश्यन्ति प्रदक्षिण पदे पदे ।।',
        'ஶ்ரீதுர்கா லக்ஷ்மீ ஸரஸ்வதீ தேவ்யை நம꞉ மந்த்ரபுஷ்பம் ஸமர்பயாமி।।
யாநி காநி ச பாபாநி ஜந்மாந்தர க்ருதாநி ச ।
தாநி தாநி விநஶ்யந்தி ப்ரதக்ஷிண பதே பதே ।।',
        'śrīdurgā lakṣmī sarasvatī devyai namaḥ mantrapuṣpaṃ samarpayāmi।।
yāni kāni ca pāpāni janmāntara kṛtāni ca ।
tāni tāni vinaśyanti pradakṣiṇa pade pade ।।',
        'Salutations to Sri Durga, Lakshmi and Saraswati: I offer the mantra-flower. Whatever wrongs were done in past births, they are destroyed at every step of the circumambulation.',
        'Pade pade, "at every step". The going round is not a gesture made once at the end but a walk, and each step counts.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), p.322');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('saraswati_pooja', 23, 'uttara', '{main,udvasana}', 'Rajopachara & Prarthana', 'ராஜோபசாரம் & ப்ரார்த்தனை',
        'Offer akshatai in place of the royal honours, then pray with joined hands.',
        'ராஜோபசாரங்களுக்குப் பதிலாக அக்ஷதை சமர்ப்பித்து, கைகூப்பி ப்ரார்த்திக்கவும்.',
        'छत्र-चामर-नृत्त-गीत-वाद्य समस्त राजोपचारार्थं
अक्षतान् समर्पयामि।।
या कुन्देन्दु-तुषार-हार-धवला या शुभ्र-वस्त्रावृता
या वीणा वर-दण्ड-मण्डित-कराया श्वेत पद्मासना।
या ब्रह्माच्युत-शङ्कर-प्रभृतिभिर्देवैः सदा पूजिता
सा मां पातु सरस्वती भगवती निःशेषजाड्यापहा।।',
        'சத்ர-சாமர-ந்ருத்த-கீத-வாத்ய ஸமஸ்த ராஜோபசாரார்தம்
அக்ஷதாந் ஸமர்பயாமி।।
யா குந்தேந்து-துஷார-ஹார-தவலா யா ஶுப்ர-வஸ்த்ராவ்ருதா
யா வீணா வர-தண்ட-மண்டித-கராயா ஶ்வேத பத்மாஸநா।
யா ப்ரஹ்மாச்யுத-ஶங்கர-ப்ரப்ருதிபிர்தேவை꞉ ஸதா பூஜிதா
ஸா மாம் பாது ஸரஸ்வதீ பகவதீ நி꞉ஶேஷஜாட்யாபஹா।।',
        'chatra-cāmara-nṛtta-gīta-vādya samasta rājopacārārthaṃ
akṣatān samarpayāmi।।
yā kundendu-tuṣāra-hāra-dhavalā yā śubhra-vastrāvṛtā
yā vīṇā vara-daṇḍa-maṇḍita-karāyā śveta padmāsanā।
yā brahmācyuta-śaṅkara-prabhṛtibhirdevaiḥ sadā pūjitā
sā māṃ pātu sarasvatī bhagavatī niḥśeṣajāḍyāpahā।।',
        'In place of the parasol, the fan, dance, song and music and all the royal honours, I offer akshatai. She who is white as the jasmine, the moon, frost and a pearl necklace, robed in white, whose hands are graced by the vina and the staff of boons, seated on the white lotus, ever worshipped by Brahma, Vishnu, Shiva and the gods: may that Goddess Saraswati, who removes all dullness, protect me.',
        'Nihshesha jadyapaha, "who removes dullness without remainder". The best known Saraswati verse asks for one thing only, to be rid of jadya, the heaviness of a mind that does not move. Every student in the house knows it by heart for that reason.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), p.322');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('saraswati_pooja', 24, 'uttara', '{main,udvasana}', 'Kshama Prarthana', 'க்ஷமா ப்ரார்த்தனை',
        'Ask the Goddess to forgive whatever was lacking in the pooja, and offer the act itself.',
        'பூஜையில் ஏற்பட்ட குறைகளை மன்னிக்கும்படி தேவியை வேண்டி, செய்த கர்மத்தை அர்ப்பணிக்கவும்.',
        'मन्त्रहीनं क्रियाहीनं भक्तिहीनं सरस्वति।
यत् पूजितं मया देवि परिपूर्णं तदस्तु ते।।
अनया पूजया श्री दुर्गा लक्ष्मी सरस्वती प्रीयताम्।।
ॐ तत् सत् ब्रह्मार्पणमस्तु।',
        'மந்த்ரஹீநம் க்ரியாஹீநம் பக்திஹீநம் ஸரஸ்வதி।
யத் பூஜிதம் மயா தேவி பரிபூர்ணம் ததஸ்து தே।।
அநயா பூஜயா ஶ்ரீ துர்கா லக்ஷ்மீ ஸரஸ்வதீ ப்ரீயதாம்।।
ஓம் தத் ஸத் ப்ரஹ்மார்பணமஸ்து।',
        'mantrahīnaṃ kriyāhīnaṃ bhaktihīnaṃ sarasvati।
yat pūjitaṃ mayā devi paripūrṇaṃ tadastu te।।
anayā pūjayā śrī durgā lakṣmī sarasvatī prīyatām।।
oṃ tat sat brahmārpaṇamastu।',
        'Lacking in mantra, lacking in rite, lacking in devotion, Saraswati: whatever I have worshipped, Goddess, let it be complete for you. By this worship may Sri Durga, Lakshmi and Saraswati be pleased. Om tat sat, let it be offered to Brahman.',
        'A student asks forgiveness of a teacher for mistakes not yet noticed. The verse makes the same request of the Goddess of learning, on the reasonable assumption that the pooja, like any recitation, was imperfect.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), p.323');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('saraswati_pooja', 25, 'uttara', '{main}', 'Upayana Danam', 'உபாயன தானம்',
        'Prostrate before the priest or an elder of the house, seek their blessing, and give them fruit, tambulam and some money with these words, after offering a seat, sandal and akshatai.',
        'புரோஹிதரையோ வீட்டுப் பெரியவரையோ நமஸ்கரித்து ஆசி பெற்று, ஆஸனம், சந்தனம், அக்ஷதை அளித்து, பழம், தாம்பூலம், தக்ஷிணை இவற்றை இந்த வாக்கியத்துடன் கொடுக்கவும்.',
        'सरस्वति स्वरूपस्य ब्राह्मणस्य इदमासनम्।
इमे गन्धाःसकलाराधनैः स्वर्चितम्।।
हिरण्यगर्भ गर्भस्थं हेमबीजं विभावसोः।
अनन्त पुण्यफलदं अतः शान्तिं प्रयच्छ मे।।
इदं उपायनं सदक्षिणाकं, सताम्बूलं, सरस्वति पूजाफल साद्गुण्यं,
सरस्वति स्वरूपाय ब्राह्मणाय तुभ्यं अहं संप्रददे न मम।।',
        'ஸரஸ்வதி ஸ்வரூபஸ்ய ப்ராஹ்மணஸ்ய இதமாஸநம்।
இமே கந்தா꞉ஸகலாராதநை꞉ ஸ்வர்சிதம்।।
ஹிரண்யகர்ப கர்பஸ்தம் ஹேமபீஜம் விபாவஸோ꞉।
அநந்த புண்யபலதம் அத꞉ ஶாந்திம் ப்ரயச்ச மே।।
இதம் உபாயநம் ஸதக்ஷிணாகம், ஸதாம்பூலம், ஸரஸ்வதி பூஜாபல ஸாத்குண்யம்,
ஸரஸ்வதி ஸ்வரூபாய ப்ராஹ்மணாய துப்யம் அஹம் ஸம்ப்ரததே ந மம।।',
        'sarasvati svarūpasya brāhmaṇasya idamāsanam।
ime gandhāḥsakalārādhanaiḥ svarcitam।।
hiraṇyagarbha garbhasthaṃ hemabījaṃ vibhāvasoḥ।
ananta puṇyaphaladaṃ ataḥ śāntiṃ prayaccha me।।
idaṃ upāyanaṃ sadakṣiṇākaṃ, satāmbūlaṃ, sarasvati pūjāphala sādguṇyaṃ,
sarasvati svarūpāya brāhmaṇāya tubhyaṃ ahaṃ saṃpradade na mama।।',
        'This seat, this sandal, and all worship are for the brahmana who is Saraswati in person. The golden seed within the womb of fire yields endless merit: so grant me peace. This gift with dakshina and tambulam, for the full fruit of the Saraswati pooja, I give to you, the brahmana who is Saraswati in person; it is no longer mine.',
        'Saraswati svarupa, "who is Saraswati in person". The gift goes to the teacher, the elder, the one who knows, as the Goddess of learning standing in the room. Na mama, "not mine", is how it is let go.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), pp.323-324');

insert into public.pooja_steps
  (pooja_id, step_number, phase, modes, step_title_en, step_title_ta,
   instruction_en, instruction_ta, mantra_sanskrit, mantra_tamil, mantra_translit,
   meaning_en, philosophy_en, gender_rule, scripts_generated, is_dynamic_sankalpam,
   namavali_id, source_ref)
values ('saraswati_pooja', 26, 'uttara', '{udvasana}', 'Punah Pooja & Yathasthanam', 'புனர் பூஜை & யதாஸ்தானம்',
        'On Vijayadashami, after the names, incense, lamp, fruit and milk and camphor, offer flowers and akshatai and move the books a little towards the north. Then take them up and read a little from each: this is the day learning begins again, and new learning is begun.',
        'விஜயதசமியன்று, நாமாவளி, தூபம், தீபம், பழம், பால், கற்பூரம் இவற்றிற்குப் பின், புஷ்பம் அக்ஷதை சமர்ப்பித்து புத்தகங்களை வடக்குப் பக்கம் சிறிது நகர்த்தவும். பின் அவற்றை எடுத்து ஒவ்வொன்றிலும் சிறிது படிக்கவும் — இன்று படிப்பு மீண்டும் தொடங்கும் நாள், புதிய கல்வி ஆரம்பிக்கும் நாள்.',
        'श्रीदुर्गां लक्ष्मीं सरस्वतीं यथास्थानं प्रतिष्ठापयामि।
शोभनार्थे क्षेमाय पुनरागमनाय च।।',
        'ஶ்ரீதுர்காம் லக்ஷ்மீம் ஸரஸ்வதீம் யதாஸ்தாநம் ப்ரதிஷ்டாபயாமி।
ஶோபநார்தே க்ஷேமாய புநராகமநாய ச।।',
        'śrīdurgāṃ lakṣmīṃ sarasvatīṃ yathāsthānaṃ pratiṣṭhāpayāmi।
śobhanārthe kṣemāya punarāgamanāya ca।।',
        'I return Sri Durga, Lakshmi and Saraswati to their places, for what is good, for well-being, and for coming again.',
        'The books go back into use the moment the Goddess is released from them. Vidyarambham, the first letters written by a child, is done on this same morning for that reason: learning that starts on Vijayadashami starts with her blessing still in the books.', 'all', true, false,
        null, 'Sampradaya Vratha Pooja Vidhi (Giri), p.324 punah pooja - yathaasthaanam');

