  ('saraswati_pooja', 1, 'Books, notebooks and pens to be worshipped, on a clean cloth', 'பூஜைக்கான புத்தகங்கள், நோட்டுப் புத்தகங்கள், பேனாக்கள் — சுத்தமான துணியின் மேல்', null, 'core', true, false, null),
  ('saraswati_pooja', 2, 'Picture or image of Saraswati', 'ஸரஸ்வதியின் படம் அல்லது விக்ரஹம்', '1', 'core', true, false, null),
  ('saraswati_pooja', 3, 'Musical instruments, tools of work, if any (veena, set of tools)', 'இசைக் கருவிகள், தொழில் கருவிகள் (இருந்தால்)', null, 'core', false, false, null),
  ('saraswati_pooja', 4, 'Kalasham (pot) with water and mango leaves', 'கலசம் (மாவிலையுடன்)', '1', 'core', true, false, null),
  ('saraswati_pooja', 5, 'Pancha pathram and uddharani (water vessel and spoon)', 'பஞ்ச பாத்திரம் & உத்தரிணி', '1 set', 'vessel', false, false, null),
  ('saraswati_pooja', 6, 'Plates (thambalam)', 'தாம்பாளம்', '2 to 3', 'vessel', false, false, null),
  ('saraswati_pooja', 7, 'Mani (pooja bell)', 'மணி', '1', 'vessel', false, false, null),
  ('saraswati_pooja', 8, 'Kuthuvilakku (oil lamp) with ghee and cotton wicks', 'குத்துவிளக்கு, நெய், திரி', '1', 'vessel', false, false, null),
  ('saraswati_pooja', 9, 'Milk, curd, ghee and honey for madhuparkam and panchamritam', 'மதுபர்க்கம் & பஞ்சாம்ருதத்திற்கு பால், தயிர், நெய், தேன்', 'a little of each', 'offering', false, false, null),
  ('saraswati_pooja', 10, 'Akshatai (rice with turmeric)', 'அக்ஷதை', null, 'offering', false, false, null),
  ('saraswati_pooja', 11, 'Manjal (turmeric) powder, kumkumam (vermilion) and kanmai (kajal paste)', 'மஞ்சள் தூள், குங்குமம், கண்மை', null, 'offering', false, false, null),
  ('saraswati_pooja', 12, 'Chandanam (sandalwood paste)', 'சந்தனம்', null, 'offering', false, false, null),
  ('saraswati_pooja', 13, 'New cloth to cover the books', 'புத்தகங்களுக்குப் போர்த்த புதுத் துணி', '1', 'offering', false, false, null),
  ('saraswati_pooja', 14, 'White flowers, loose and a garland (jasmine, white lotus)', 'வெண்மையான புஷ்பங்கள் & மாலை (மல்லிகை, வெண்தாமரை)', null, 'flower', false, false, null),
  ('saraswati_pooja', 15, 'Agarbatti and karpooram (incense sticks and camphor)', 'ஊதுபத்தி & கற்பூரம்', null, 'offering', false, false, null),
  ('saraswati_pooja', 16, 'Vetrilai and paakku (betel leaves and areca nut)', 'வெற்றிலை & பாக்கு', null, 'offering', false, false, null),
  ('saraswati_pooja', 17, 'Fruit, tambulam and dakshina for the upayana danam', 'உபாயன தானத்திற்கு பழம், தாம்பூலம், தக்ஷிணை', null, 'offering', false, false, null);

